DO $$
DECLARE
    v_missing_groups text;
    v_wrong_group_paths text;
    v_missing_commands text;
    v_wrong_command_groups text;
    v_wrong_target_paths text;
    v_missing_bindings text;
    v_counts text;
    v_old_root integer;
BEGIN
    SELECT string_agg(t.group_code, E'
' ORDER BY t.group_code) INTO v_missing_groups
    FROM tmp_mml_350_groups t
    LEFT JOIN public.mml_command_groups g ON g.param_version = t.param_version AND g.group_code = t.group_code AND g.deleted_at IS NULL AND g.deprecated_at IS NULL
    WHERE g.id IS NULL;
    IF v_missing_groups IS NOT NULL THEN
        RAISE EXCEPTION 'missing groups:%', E'
' || v_missing_groups;
    END IF;

    SELECT string_agg(t.group_code || ' expected=' || t.path_text || ' actual=' || g.path::text, E'
' ORDER BY t.group_code)
      INTO v_wrong_group_paths
    FROM tmp_mml_350_groups t
    JOIN public.mml_command_groups g ON g.param_version = t.param_version AND g.group_code = t.group_code AND g.deleted_at IS NULL AND g.deprecated_at IS NULL
    WHERE g.path::text <> t.path_text;
    IF v_wrong_group_paths IS NOT NULL THEN
        RAISE EXCEPTION 'wrong group paths:%', E'
' || v_wrong_group_paths;
    END IF;

    SELECT COUNT(*) INTO v_old_root
    FROM public.mml_command_groups g
    WHERE g.param_version = 'cmcc-td-lte-v2.3' AND g.group_code = 'MML350_20260704' AND g.deleted_at IS NULL AND g.deprecated_at IS NULL;
    IF v_old_root <> 0 THEN
        RAISE EXCEPTION 'old supplemental root % still exists', 'MML350_20260704';
    END IF;

    SELECT string_agg(t.command_code, E'
' ORDER BY t.command_code) INTO v_missing_commands
    FROM tmp_mml_350_commands t
    LEFT JOIN public.mml_commands c ON c.command_code = t.command_code AND c.deprecated_at IS NULL
    WHERE c.id IS NULL;
    IF v_missing_commands IS NOT NULL THEN
        RAISE EXCEPTION 'missing commands:%', E'
' || v_missing_commands;
    END IF;

    SELECT string_agg(t.command_code || ' expected_group=' || t.group_code || ' actual_group=' || COALESCE(g.group_code, '<null>'), E'
' ORDER BY t.command_code)
      INTO v_wrong_command_groups
    FROM tmp_mml_350_commands t
    JOIN public.mml_commands c ON c.command_code = t.command_code AND c.deprecated_at IS NULL
    LEFT JOIN public.mml_command_groups g ON g.id = c.group_id
    WHERE g.group_code IS DISTINCT FROM t.group_code;
    IF v_wrong_command_groups IS NOT NULL THEN
        RAISE EXCEPTION 'wrong command group placement:%', E'
' || v_wrong_command_groups;
    END IF;

    SELECT string_agg(t.command_code, E'
' ORDER BY t.command_code) INTO v_wrong_target_paths
    FROM tmp_mml_350_commands t
    JOIN public.mml_commands c ON c.command_code = t.command_code AND c.deprecated_at IS NULL
    WHERE NOT (c.target_paths @> t.target_paths AND t.target_paths @> c.target_paths);
    IF v_wrong_target_paths IS NOT NULL THEN
        RAISE EXCEPTION 'wrong command target_paths:%', E'
' || v_wrong_target_paths;
    END IF;

    SELECT string_agg(s.command_code || ' / ' || s.standard_path, E'
' ORDER BY s.command_code, s.standard_path)
      INTO v_missing_bindings
    FROM tmp_mml_350_sub_fields s
    JOIN public.mml_commands c ON c.command_code = s.command_code AND c.deprecated_at IS NULL
    JOIN public.standard_params sp ON sp.standard_path = s.standard_path AND sp.entry_type = 'parameter'
    LEFT JOIN public.mml_command_sub_fields csf ON csf.command_id = c.id AND csf.standard_path_id = sp.id AND csf.deprecated_at IS NULL
    WHERE csf.id IS NULL;
    IF v_missing_bindings IS NOT NULL THEN
        RAISE EXCEPTION 'missing command-path bindings:%', E'
' || v_missing_bindings;
    END IF;

    WITH actual AS (
        SELECT
            (SELECT COUNT(*) FROM tmp_mml_350_groups) AS expected_groups,
            (SELECT COUNT(*) FROM tmp_mml_350_commands) AS expected_commands,
            (SELECT COUNT(*) FROM tmp_mml_350_sub_fields) AS expected_bindings,
            (SELECT COUNT(*) FROM tmp_mml_350_groups t JOIN public.mml_command_groups g ON g.param_version=t.param_version AND g.group_code=t.group_code AND g.deleted_at IS NULL AND g.deprecated_at IS NULL) AS actual_groups,
            (SELECT COUNT(*) FROM tmp_mml_350_commands t JOIN public.mml_commands c ON c.command_code=t.command_code AND c.deprecated_at IS NULL) AS actual_commands,
            (SELECT COUNT(*) FROM tmp_mml_350_sub_fields s JOIN public.mml_commands c ON c.command_code=s.command_code AND c.deprecated_at IS NULL JOIN public.standard_params sp ON sp.standard_path=s.standard_path AND sp.entry_type='parameter' JOIN public.mml_command_sub_fields csf ON csf.command_id=c.id AND csf.standard_path_id=sp.id AND csf.deprecated_at IS NULL) AS actual_bindings
    )
    SELECT 'expected_groups=' || expected_groups || ', actual_groups=' || actual_groups ||
           ', expected_commands=' || expected_commands || ', actual_commands=' || actual_commands ||
           ', expected_bindings=' || expected_bindings || ', actual_bindings=' || actual_bindings
      INTO v_counts
    FROM actual;
    RAISE NOTICE 'mml_350_verify_ok: %', v_counts;
END $$;

SELECT 'document_rows' AS metric, COUNT(*)::text AS value FROM tmp_mml_350_sub_fields
UNION ALL SELECT 'document_paths', COUNT(DISTINCT standard_path)::text FROM tmp_mml_350_sub_fields
UNION ALL SELECT 'excel_groups', COUNT(*)::text FROM tmp_mml_350_groups
UNION ALL SELECT 'excel_group_command_pairs', COUNT(*)::text FROM tmp_mml_350_commands
UNION ALL SELECT 'expected_bindings', COUNT(*)::text FROM tmp_mml_350_sub_fields
ORDER BY metric;

SELECT source_group_name AS excel_group, COUNT(*) AS path_rows, COUNT(DISTINCT source_command_name) AS command_nodes
FROM tmp_mml_350_sub_fields
GROUP BY source_group_name
ORDER BY MIN(source_row);

COMMIT;
-- END former mml_add_350_new_command_nodes_20260704_verify.sql

\echo 'Verifying MML standard TRPath remaining regrouping (20260723)...'
BEGIN;
DO $$
DECLARE
    v_groups integer;
    v_visible_groups integer;
    v_commands integer;
    v_fields integer;
BEGIN
    SELECT COUNT(*) INTO v_groups
    FROM public.mml_command_groups
    WHERE group_code LIKE 'MML_STD_TRPATH_G%';

    SELECT COUNT(*) INTO v_visible_groups
    FROM public.mml_command_groups g
    WHERE g.group_code LIKE 'MML_STD_TRPATH_G%'
      AND g.path IS NOT NULL
      AND g.deleted_at IS NULL
      AND g.deprecated_at IS NULL
      AND ((g.source = 'standard' AND COALESCE(g.chapter_code, '') <> '') OR g.source = 'admin');

    SELECT COUNT(*) INTO v_commands
    FROM public.mml_commands
    WHERE command_code LIKE '% STD_TRPATH_G%'
      AND deprecated_at IS NULL;

    SELECT COUNT(*) INTO v_fields
    FROM public.mml_command_sub_fields sf
    JOIN public.mml_commands c ON c.id = sf.command_id
    WHERE c.command_code LIKE '% STD_TRPATH_G%'
      AND c.deprecated_at IS NULL
      AND sf.deprecated_at IS NULL;

    IF v_groups <> 14 OR v_visible_groups <> 14 OR v_commands <> 28 OR v_fields <> 436 THEN
        RAISE EXCEPTION 'MML standard TRPath regrouping verify failed: groups=%, visible_groups=%, commands=%, fields=%',
            v_groups, v_visible_groups, v_commands, v_fields;
    END IF;
END $$;
SELECT
    COUNT(*) FILTER (WHERE g.group_code LIKE 'MML_STD_TRPATH_G%') AS groups,
    COUNT(*) FILTER (
        WHERE g.group_code LIKE 'MML_STD_TRPATH_G%'
          AND g.path IS NOT NULL
          AND g.deleted_at IS NULL
          AND g.deprecated_at IS NULL
          AND ((g.source = 'standard' AND COALESCE(g.chapter_code, '') <> '') OR g.source = 'admin')
    ) AS visible_groups
FROM public.mml_command_groups g;
ROLLBACK;
-- END MML standard TRPath remaining regrouping verify (20260723)

\elif :{?mml_rollback}
\echo 'Rolling back MML new command nodes...'
-- BEGIN former mml_add_350_new_command_nodes_20260704_rollback.sql
