-- BEGIN Device.FAP writable MOD commands
BEGIN;

WITH target_lst(command_code) AS (
    VALUES
        ('LST MML350_DEVICE_FAP__HANRU'),
        ('LST MML350_DEVICE_FAP__IPSEC'),
        ('LST MML350_DEVICE_FAP__LANCONFIG'),
        ('LST MML350_DEVICE_FAP__NL'),
        ('LST MML350_DEVICE_FAP__PTP1588'),
        ('LST MML350_DEVICE_FAP__SYNCHRONIZATION'),
        ('LST MML350_DEVICE_FAP__TFCS'),
        ('LST MML350_DEVICE_FAP__TFCSPARAMS')
), rw_paths AS (
    SELECT
        c.command_code AS lst_command_code,
        replace(c.command_code, 'LST ', 'MOD ') AS mod_command_code,
        c.category,
        c.description,
        c.group_id,
        c.logical_name_i18n,
        COALESCE(c.logical_name_i18n->>'zh-CN', c.command_name) AS logical_zh,
        COALESCE(c.logical_name_i18n->>'en-US', c.command_name) AS logical_en,
        jsonb_agg(to_jsonb(sp.standard_path) ORDER BY sf.sort_order) AS target_paths
    FROM target_lst t
    JOIN public.mml_commands c ON c.command_code = t.command_code AND c.deprecated_at IS NULL
    JOIN public.mml_command_sub_fields sf ON sf.command_id = c.id AND sf.deprecated_at IS NULL AND sf.access_type = 'RW'
    JOIN public.standard_params sp ON sp.id = sf.standard_path_id
    GROUP BY c.command_code, c.category, c.description, c.group_id, c.logical_name_i18n, c.command_name
), upserted AS (
    INSERT INTO public.mml_commands (
        command_name, command_code, category, description, rpc_method,
        target_paths, group_id, command_name_i18n, require_confirm,
        confirm_msg_i18n, operation_type, logical_name_i18n, source,
        catalog_protected, platform_tags, tree_node_refs
    )
    SELECT
        '修改 ' || logical_zh,
        mod_command_code,
        category,
        description,
        'SetParameterValues',
        target_paths,
        group_id,
        jsonb_build_object('zh-CN', '修改 ' || logical_zh, 'en-US', 'Modify ' || logical_en),
        false,
        '{}'::jsonb,
        'MOD',
        logical_name_i18n,
        'admin',
        false,
        '{}'::jsonb,
        target_paths
    FROM rw_paths
    ON CONFLICT (command_code) DO UPDATE
    SET command_name = EXCLUDED.command_name,
        category = EXCLUDED.category,
        description = EXCLUDED.description,
        rpc_method = EXCLUDED.rpc_method,
        target_paths = EXCLUDED.target_paths,
        group_id = EXCLUDED.group_id,
        command_name_i18n = EXCLUDED.command_name_i18n,
        operation_type = EXCLUDED.operation_type,
        logical_name_i18n = EXCLUDED.logical_name_i18n,
        tree_node_refs = EXCLUDED.tree_node_refs,
        deprecated_at = NULL,
        updated_at = NOW()
    RETURNING id, command_code
)
INSERT INTO public.mml_command_sub_fields (
    command_id, mml_code, label_i18n, default_selected, is_required,
    sort_order, standard_path_id, access_type, is_supported
)
SELECT
    u.id,
    sf.mml_code,
    sf.label_i18n,
    sf.default_selected,
    sf.is_required,
    sf.sort_order,
    sf.standard_path_id,
    sf.access_type,
    sf.is_supported
FROM target_lst t
JOIN public.mml_commands lst ON lst.command_code = t.command_code AND lst.deprecated_at IS NULL
JOIN public.mml_command_sub_fields sf ON sf.command_id = lst.id AND sf.deprecated_at IS NULL AND sf.access_type = 'RW'
JOIN upserted u ON u.command_code = replace(lst.command_code, 'LST ', 'MOD ')
ON CONFLICT (command_id, standard_path_id) DO UPDATE
SET mml_code = EXCLUDED.mml_code,
    label_i18n = EXCLUDED.label_i18n,
    default_selected = EXCLUDED.default_selected,
    is_required = EXCLUDED.is_required,
    sort_order = EXCLUDED.sort_order,
    access_type = EXCLUDED.access_type,
    is_supported = EXCLUDED.is_supported,
    deprecated_at = NULL,
    updated_at = NOW();

COMMIT;
-- END Device.FAP writable MOD commands

-- BEGIN GPS flat command list cleanup
BEGIN;

WITH gps AS (
    SELECT id
    FROM public.mml_command_groups
    WHERE param_version = 'cmcc-td-lte-v2.3'
      AND group_code = 'chapter:SO'
      AND deleted_at IS NULL
    LIMIT 1
), bucket_groups AS (
    SELECT id
    FROM public.mml_command_groups
    WHERE param_version = 'cmcc-td-lte-v2.3'
      AND group_code IN ('chapter:SO:QUERY', 'chapter:SO:MODIFY')
)
UPDATE public.mml_commands c
SET group_id = gps.id,
    updated_at = NOW()
FROM gps, bucket_groups
WHERE c.deprecated_at IS NULL
  AND c.group_id = bucket_groups.id;

DELETE FROM public.mml_command_groups
WHERE param_version = 'cmcc-td-lte-v2.3'
  AND group_code IN ('chapter:SO:QUERY', 'chapter:SO:MODIFY')
  AND NOT EXISTS (
      SELECT 1
      FROM public.mml_commands c
      WHERE c.group_id = mml_command_groups.id
  );

COMMIT;
-- END GPS flat command list cleanup

-- BEGIN GPS merged query/modify commands
BEGIN;

WITH gps AS (
    SELECT id
    FROM public.mml_command_groups
    WHERE param_version = 'cmcc-td-lte-v2.3'
      AND group_code = 'chapter:SO'
      AND deleted_at IS NULL
    LIMIT 1
), target_cmds AS (
    UPDATE public.mml_commands c
    SET group_id = gps.id,
        command_name = CASE c.command_code
            WHEN 'LST SO_SUB_01' THEN '查询 GPS信息参数管理'
            WHEN 'MOD SO_SUB_01' THEN '修改 GPS信息参数管理'
            ELSE c.command_name
        END,
        command_name_i18n = CASE c.command_code
            WHEN 'LST SO_SUB_01' THEN '{"zh-CN":"查询 GPS信息参数管理","en-US":"Query GPS Information Parameters"}'::jsonb
            WHEN 'MOD SO_SUB_01' THEN '{"zh-CN":"修改 GPS信息参数管理","en-US":"Modify GPS Information Parameters"}'::jsonb
            ELSE c.command_name_i18n
        END,
        logical_name_i18n = '{"zh-CN":"GPS信息参数管理","en-US":"GPS Information Parameters"}'::jsonb,
        deprecated_at = NULL,
        updated_at = NOW()
    FROM gps
    WHERE c.command_code IN ('LST SO_SUB_01', 'MOD SO_SUB_01')
    RETURNING c.id, c.command_code
), source_raw AS (
    SELECT
        src_rank.rank_no,
        sf.mml_code,
        sf.label_i18n,
        sf.default_selected,
        sf.is_required,
        sf.sort_order AS source_sort_order,
        sf.standard_path_id,
        sf.access_type,
        sf.is_supported,
        sp.standard_path
    FROM (VALUES
        ('LST SO_SUB_01', 1),
        ('LST MML350_DEVICE_FAP__SYNCHRONIZATION', 2),
        ('LST MML350_DEVICE_FAP__TFCS', 3),
        ('LST MML350_DEVICE_FAP__TFCSPARAMS', 4)
    ) AS src_rank(command_code, rank_no)
    JOIN public.mml_commands src ON src.command_code = src_rank.command_code
    JOIN public.mml_command_sub_fields sf ON sf.command_id = src.id AND sf.deprecated_at IS NULL
    JOIN public.standard_params sp ON sp.id = sf.standard_path_id
), source_dedup AS (
    SELECT DISTINCT ON (standard_path_id) *
    FROM source_raw
    ORDER BY standard_path_id, rank_no, source_sort_order, standard_path
), lst_source AS (
    SELECT
        *,
        row_number() OVER (ORDER BY rank_no, source_sort_order, standard_path) AS merged_sort_order,
        count(*) OVER (PARTITION BY mml_code) AS mml_code_count
    FROM source_dedup
), lst_insert AS (
    INSERT INTO public.mml_command_sub_fields (
        command_id, mml_code, label_i18n, default_selected, is_required,
        sort_order, standard_path_id, access_type, is_supported
    )
    SELECT
        target_cmds.id,
        CASE
            WHEN lst_source.mml_code_count > 1 THEN LEFT(UPPER(regexp_replace(replace(lst_source.standard_path, 'Device.FAP.', ''), '[^A-Za-z0-9]+', '_', 'g')), 100)
            ELSE lst_source.mml_code
        END,
        lst_source.label_i18n,
        lst_source.default_selected,
        lst_source.is_required,
        lst_source.merged_sort_order,
        lst_source.standard_path_id,
        lst_source.access_type,
        lst_source.is_supported
    FROM target_cmds
    CROSS JOIN lst_source
    WHERE target_cmds.command_code = 'LST SO_SUB_01'
    ON CONFLICT (command_id, standard_path_id) DO UPDATE
    SET mml_code = EXCLUDED.mml_code,
        label_i18n = EXCLUDED.label_i18n,
        default_selected = EXCLUDED.default_selected,
        is_required = EXCLUDED.is_required,
        sort_order = EXCLUDED.sort_order,
        access_type = EXCLUDED.access_type,
        is_supported = EXCLUDED.is_supported,
        deprecated_at = NULL,
        updated_at = NOW()
    RETURNING 1
), mod_source AS (
    SELECT
        *,
        row_number() OVER (ORDER BY rank_no, source_sort_order, standard_path) AS merged_sort_order,
        count(*) OVER (PARTITION BY mml_code) AS mml_code_count
    FROM source_dedup
    WHERE access_type = 'RW'
), mod_insert AS (
    INSERT INTO public.mml_command_sub_fields (
        command_id, mml_code, label_i18n, default_selected, is_required,
        sort_order, standard_path_id, access_type, is_supported
    )
    SELECT
        target_cmds.id,
        CASE
            WHEN mod_source.mml_code_count > 1 THEN LEFT(UPPER(regexp_replace(replace(mod_source.standard_path, 'Device.FAP.', ''), '[^A-Za-z0-9]+', '_', 'g')), 100)
            ELSE mod_source.mml_code
        END,
        mod_source.label_i18n,
        mod_source.default_selected,
        mod_source.is_required,
        mod_source.merged_sort_order,
        mod_source.standard_path_id,
        'RW',
        mod_source.is_supported
    FROM target_cmds
    CROSS JOIN mod_source
    WHERE target_cmds.command_code = 'MOD SO_SUB_01'
    ON CONFLICT (command_id, standard_path_id) DO UPDATE
    SET mml_code = EXCLUDED.mml_code,
        label_i18n = EXCLUDED.label_i18n,
        default_selected = EXCLUDED.default_selected,
        is_required = EXCLUDED.is_required,
        sort_order = EXCLUDED.sort_order,
        access_type = EXCLUDED.access_type,
        is_supported = EXCLUDED.is_supported,
        deprecated_at = NULL,
        updated_at = NOW()
    RETURNING 1
)
UPDATE public.mml_commands c
SET deprecated_at = NOW(),
    updated_at = NOW()
WHERE c.command_code IN (
    'LST MML350_DEVICE_FAP__SYNCHRONIZATION',
    'LST MML350_DEVICE_FAP__TFCS',
    'LST MML350_DEVICE_FAP__TFCSPARAMS',
    'MOD MML350_DEVICE_FAP__SYNCHRONIZATION',
    'MOD MML350_DEVICE_FAP__TFCS',
    'MOD MML350_DEVICE_FAP__TFCSPARAMS'
);

COMMIT;
-- END GPS merged query/modify commands

-- BEGIN NeighborList coverage under neighbor cell parameter group
BEGIN;

WITH si_group AS (
    SELECT id
    FROM public.mml_command_groups
    WHERE group_code = 'chapter:SI'
      AND param_version = 'cmcc-td-lte-v2.3'
      AND deleted_at IS NULL
    ORDER BY updated_at DESC
    LIMIT 1
), desired_commands(command_code, command_name_zh, command_name_en, logical_name_zh, logical_name_en, operation_type, rpc_method, target_object) AS (
    VALUES
        ('ADD 5G_CELL', '新增 5G邻区', 'Add 5G Neighbor Cell', '5G邻区', '5G Neighbor Cell', 'ADD', 'AddObject', 'Device.Services.FAPService.CellConfig.LTE.RAN.NeighborList.5GCell.'),
        ('RMV 5G_CELL', '删除 5G邻区', 'Remove 5G Neighbor Cell', '5G邻区', '5G Neighbor Cell', 'RMV', 'DeleteObject', 'Device.Services.FAPService.CellConfig.LTE.RAN.NeighborList.5GCell.'),
        ('ADD INTER_RAT_CELL_NR', '新增 NR异系统邻区', 'Add NR Inter-RAT Neighbor Cell', 'NR异系统邻区', 'NR Inter-RAT Neighbor Cell', 'ADD', 'AddObject', 'Device.Services.FAPService.CellConfig.LTE.RAN.NeighborList.InterRATCell.NR.'),
        ('RMV INTER_RAT_CELL_NR', '删除 NR异系统邻区', 'Remove NR Inter-RAT Neighbor Cell', 'NR异系统邻区', 'NR Inter-RAT Neighbor Cell', 'RMV', 'DeleteObject', 'Device.Services.FAPService.CellConfig.LTE.RAN.NeighborList.InterRATCell.NR.'),
        ('ADD INTER_RAT_CELL_UMTS', '新增 UMTS异系统邻区', 'Add UMTS Inter-RAT Neighbor Cell', 'UMTS异系统邻区', 'UMTS Inter-RAT Neighbor Cell', 'ADD', 'AddObject', 'Device.Services.FAPService.CellConfig.LTE.RAN.NeighborList.InterRATCell.UMTS.'),
        ('RMV INTER_RAT_CELL_UMTS', '删除 UMTS异系统邻区', 'Remove UMTS Inter-RAT Neighbor Cell', 'UMTS异系统邻区', 'UMTS Inter-RAT Neighbor Cell', 'RMV', 'DeleteObject', 'Device.Services.FAPService.CellConfig.LTE.RAN.NeighborList.InterRATCell.UMTS.'),
        ('ADD INTER_RAT_CELL_GSM', '新增 GSM异系统邻区', 'Add GSM Inter-RAT Neighbor Cell', 'GSM异系统邻区', 'GSM Inter-RAT Neighbor Cell', 'ADD', 'AddObject', 'Device.Services.FAPService.CellConfig.LTE.RAN.NeighborList.InterRATCell.GSM.'),
        ('RMV INTER_RAT_CELL_GSM', '删除 GSM异系统邻区', 'Remove GSM Inter-RAT Neighbor Cell', 'GSM异系统邻区', 'GSM Inter-RAT Neighbor Cell', 'RMV', 'DeleteObject', 'Device.Services.FAPService.CellConfig.LTE.RAN.NeighborList.InterRATCell.GSM.'),
        ('ADD LTE_CELL', '新增 LTE同系统邻区', 'Add LTE Neighbor Cell', 'LTE同系统邻区', 'LTE Neighbor Cell', 'ADD', 'AddObject', 'Device.Services.FAPService.CellConfig.LTE.RAN.NeighborList.LTECell.'),
        ('RMV LTE_CELL', '删除 LTE同系统邻区', 'Remove LTE Neighbor Cell', 'LTE同系统邻区', 'LTE Neighbor Cell', 'RMV', 'DeleteObject', 'Device.Services.FAPService.CellConfig.LTE.RAN.NeighborList.LTECell.')
)
INSERT INTO public.mml_commands (
    command_name, command_code, category, description, rpc_method, target_paths,
    target_object, group_id, command_name_i18n, require_confirm, confirm_msg_i18n,
    operation_type, logical_name_i18n, source, catalog_protected, platform_tags,
    deprecated_at, tree_node_refs, instance_range_meta, help_doc, notes
)
SELECT
    d.command_name_zh,
    d.command_code,
    'neighbor-list-coverage',
    'NeighborList multi-instance operation restored for MML neighbor cell group',
    d.rpc_method,
    jsonb_build_array(d.target_object),
    d.target_object,
    g.id,
    jsonb_build_object('zh-CN', d.command_name_zh, 'en-US', d.command_name_en),
    false,
    '{}'::jsonb,
    d.operation_type,
    jsonb_build_object('zh-CN', d.logical_name_zh, 'en-US', d.logical_name_en),
    'standard',
    true,
    '{}'::jsonb,
    NULL,
    jsonb_build_array(d.target_object),
    '[]'::jsonb,
    '',
    ''
FROM desired_commands d
CROSS JOIN si_group g
ON CONFLICT (command_code) DO UPDATE
SET command_name = EXCLUDED.command_name,
    category = EXCLUDED.category,
    description = EXCLUDED.description,
    rpc_method = EXCLUDED.rpc_method,
    target_object = EXCLUDED.target_object,
    group_id = EXCLUDED.group_id,
    command_name_i18n = EXCLUDED.command_name_i18n,
    operation_type = EXCLUDED.operation_type,
    logical_name_i18n = EXCLUDED.logical_name_i18n,
    source = EXCLUDED.source,
    catalog_protected = EXCLUDED.catalog_protected,
    deprecated_at = NULL,
    updated_at = NOW();

WITH neighbor_paths AS (
    SELECT
        sp.id AS standard_path_id,
        sp.standard_path,
        CASE
            WHEN sp.standard_path LIKE 'Device.Services.FAPService.%CellConfig.LTE.RAN.NeighborList.5GCell.%' THEN '5G'
            WHEN sp.standard_path LIKE 'Device.Services.FAPService.%CellConfig.LTE.RAN.NeighborList.InterRATCell.NR.%' THEN 'NR'
            WHEN sp.standard_path LIKE 'Device.Services.FAPService.%CellConfig.LTE.RAN.NeighborList.InterRATCell.UMTS.%' THEN 'UMTS'
            WHEN sp.standard_path LIKE 'Device.Services.FAPService.%CellConfig.LTE.RAN.NeighborList.InterRATCell.GSM.%' THEN 'GSM'
            WHEN sp.standard_path LIKE 'Device.Services.FAPService.%CellConfig.LTE.RAN.NeighborList.LTECell.%'
              OR sp.standard_path LIKE 'Device.Services.FAPService.%CellConfig.{i}.LTE.RAN.NeighborList.LTECell.%'
              OR sp.standard_path LIKE 'Device.Services.FAPService.%CellConfig.LTE.RAN.NeighborListInUse.LTECell.%' THEN 'LTE'
        END AS bucket,
        CASE WHEN sp.access = 'READ_WRITE' THEN 'RW' ELSE 'RO' END AS access_type,
        row_number() OVER (
            PARTITION BY
                CASE
                    WHEN sp.standard_path LIKE 'Device.Services.FAPService.%CellConfig.LTE.RAN.NeighborList.5GCell.%' THEN '5G'
                    WHEN sp.standard_path LIKE 'Device.Services.FAPService.%CellConfig.LTE.RAN.NeighborList.InterRATCell.NR.%' THEN 'NR'
                    WHEN sp.standard_path LIKE 'Device.Services.FAPService.%CellConfig.LTE.RAN.NeighborList.InterRATCell.UMTS.%' THEN 'UMTS'
                    WHEN sp.standard_path LIKE 'Device.Services.FAPService.%CellConfig.LTE.RAN.NeighborList.InterRATCell.GSM.%' THEN 'GSM'
                    WHEN sp.standard_path LIKE 'Device.Services.FAPService.%CellConfig.LTE.RAN.NeighborList.LTECell.%'
                      OR sp.standard_path LIKE 'Device.Services.FAPService.%CellConfig.LTE.RAN.NeighborListInUse.LTECell.%' THEN 'LTE'
                END
            ORDER BY sp.standard_path
        ) AS bucket_order,
        LEFT(UPPER(regexp_replace(replace(replace(sp.standard_path, 'Device.Services.FAPService.{i}.CellConfig.LTE.RAN.NeighborListInUse.', 'IN_USE.'), 'Device.Services.FAPService.{i}.CellConfig.LTE.RAN.NeighborList.', ''), '[^A-Za-z0-9]+', '_', 'g')), 91)
            || '_' || substr(md5(sp.standard_path), 1, 8) AS mml_code
    FROM public.standard_params sp
    WHERE (sp.standard_path LIKE 'Device.Services.FAPService.%CellConfig.LTE.RAN.NeighborList%'
        OR sp.standard_path LIKE 'Device.Services.FAPService.%CellConfig.{i}.LTE.RAN.NeighborList%')
      AND sp.entry_type = 'parameter'
), command_path_targets AS (
    SELECT 'LST SI_SUB_01' AS command_code, standard_path_id, standard_path, access_type, bucket_order, mml_code FROM neighbor_paths WHERE bucket IN ('5G', 'NR')
    UNION ALL SELECT 'MOD SI_SUB_01', standard_path_id, standard_path, access_type, bucket_order, mml_code FROM neighbor_paths WHERE bucket IN ('5G', 'NR') AND access_type = 'RW'
    UNION ALL SELECT 'LST SI_SUB_02', standard_path_id, standard_path, access_type, bucket_order, mml_code FROM neighbor_paths WHERE bucket = 'LTE'
    UNION ALL SELECT 'MOD SI_SUB_02', standard_path_id, standard_path, access_type, bucket_order, mml_code FROM neighbor_paths WHERE bucket = 'LTE' AND access_type = 'RW'
    UNION ALL SELECT 'LST SI_SUB_03', standard_path_id, standard_path, access_type, bucket_order, mml_code FROM neighbor_paths WHERE bucket = 'UMTS'
    UNION ALL SELECT 'MOD SI_SUB_03', standard_path_id, standard_path, access_type, bucket_order, mml_code FROM neighbor_paths WHERE bucket = 'UMTS' AND access_type = 'RW'
    UNION ALL SELECT 'LST SI_SUB_04', standard_path_id, standard_path, access_type, bucket_order, mml_code FROM neighbor_paths WHERE bucket = 'GSM'
    UNION ALL SELECT 'MOD SI_SUB_04', standard_path_id, standard_path, access_type, bucket_order, mml_code FROM neighbor_paths WHERE bucket = 'GSM' AND access_type = 'RW'
    UNION ALL SELECT 'ADD 5G_CELL', standard_path_id, standard_path, access_type, bucket_order, mml_code FROM neighbor_paths WHERE bucket = '5G' AND access_type = 'RW'
    UNION ALL SELECT 'RMV 5G_CELL', standard_path_id, standard_path, access_type, bucket_order, mml_code FROM neighbor_paths WHERE bucket = '5G'
    UNION ALL SELECT 'ADD INTER_RAT_CELL_NR', standard_path_id, standard_path, access_type, bucket_order, mml_code FROM neighbor_paths WHERE bucket = 'NR' AND access_type = 'RW'
    UNION ALL SELECT 'RMV INTER_RAT_CELL_NR', standard_path_id, standard_path, access_type, bucket_order, mml_code FROM neighbor_paths WHERE bucket = 'NR'
    UNION ALL SELECT 'ADD INTER_RAT_CELL_UMTS', standard_path_id, standard_path, access_type, bucket_order, mml_code FROM neighbor_paths WHERE bucket = 'UMTS' AND access_type = 'RW'
    UNION ALL SELECT 'RMV INTER_RAT_CELL_UMTS', standard_path_id, standard_path, access_type, bucket_order, mml_code FROM neighbor_paths WHERE bucket = 'UMTS'
    UNION ALL SELECT 'ADD INTER_RAT_CELL_GSM', standard_path_id, standard_path, access_type, bucket_order, mml_code FROM neighbor_paths WHERE bucket = 'GSM' AND access_type = 'RW'
    UNION ALL SELECT 'RMV INTER_RAT_CELL_GSM', standard_path_id, standard_path, access_type, bucket_order, mml_code FROM neighbor_paths WHERE bucket = 'GSM'
    UNION ALL SELECT 'ADD LTE_CELL', standard_path_id, standard_path, access_type, bucket_order, mml_code FROM neighbor_paths WHERE bucket = 'LTE' AND standard_path NOT LIKE '%NeighborListInUse%' AND access_type = 'RW'
    UNION ALL SELECT 'RMV LTE_CELL', standard_path_id, standard_path, access_type, bucket_order, mml_code FROM neighbor_paths WHERE bucket = 'LTE' AND standard_path NOT LIKE '%NeighborListInUse%'
), numbered AS (
    SELECT
        cpt.*,
        row_number() OVER (PARTITION BY command_code ORDER BY bucket_order, standard_path) AS sort_order
    FROM command_path_targets cpt
), target_cmds AS (
    SELECT id, command_code, operation_type
    FROM public.mml_commands
    WHERE command_code IN (
        'LST SI_SUB_01', 'MOD SI_SUB_01', 'LST SI_SUB_02', 'MOD SI_SUB_02',
        'LST SI_SUB_03', 'MOD SI_SUB_03', 'LST SI_SUB_04', 'MOD SI_SUB_04',
        'ADD 5G_CELL', 'RMV 5G_CELL',
        'ADD INTER_RAT_CELL_NR', 'RMV INTER_RAT_CELL_NR',
        'ADD INTER_RAT_CELL_UMTS', 'RMV INTER_RAT_CELL_UMTS',
        'ADD INTER_RAT_CELL_GSM', 'RMV INTER_RAT_CELL_GSM',
        'ADD LTE_CELL', 'RMV LTE_CELL'
    )
      AND deprecated_at IS NULL
)
INSERT INTO public.mml_command_sub_fields (
    command_id, mml_code, label_i18n, default_selected, is_required,
    sort_order, standard_path_id, access_type, is_supported
)
SELECT
    tc.id,
    n.mml_code,
    jsonb_build_object('zh-CN', n.mml_code, 'en-US', initcap(replace(lower(n.mml_code), '_', ' '))),
    true,
    tc.operation_type IN ('MOD', 'ADD'),
    n.sort_order,
    n.standard_path_id,
    n.access_type,
    true
FROM numbered n
JOIN target_cmds tc ON tc.command_code = n.command_code
ON CONFLICT (command_id, standard_path_id) DO UPDATE
SET mml_code = EXCLUDED.mml_code,
    label_i18n = EXCLUDED.label_i18n,
    default_selected = EXCLUDED.default_selected,
    is_required = EXCLUDED.is_required,
    sort_order = EXCLUDED.sort_order,
    access_type = EXCLUDED.access_type,
    is_supported = EXCLUDED.is_supported,
    deprecated_at = NULL,
    updated_at = NOW();

WITH target_cmds AS (
    SELECT id
    FROM public.mml_commands
    WHERE command_code IN (
        'LST SI_SUB_01', 'MOD SI_SUB_01', 'LST SI_SUB_02', 'MOD SI_SUB_02',
        'LST SI_SUB_03', 'MOD SI_SUB_03', 'LST SI_SUB_04', 'MOD SI_SUB_04',
        'ADD 5G_CELL', 'RMV 5G_CELL',
        'ADD INTER_RAT_CELL_NR', 'RMV INTER_RAT_CELL_NR',
        'ADD INTER_RAT_CELL_UMTS', 'RMV INTER_RAT_CELL_UMTS',
        'ADD INTER_RAT_CELL_GSM', 'RMV INTER_RAT_CELL_GSM',
        'ADD LTE_CELL', 'RMV LTE_CELL'
    )
), refreshed AS (
    SELECT
        t.id,
        COALESCE(jsonb_agg(sp.standard_path ORDER BY sf.sort_order, sp.standard_path)
                 FILTER (WHERE sp.standard_path IS NOT NULL), '[]'::jsonb) AS paths
    FROM target_cmds t
    LEFT JOIN public.mml_command_sub_fields sf ON sf.command_id = t.id AND sf.deprecated_at IS NULL
    LEFT JOIN public.standard_params sp ON sp.id = sf.standard_path_id
    GROUP BY t.id
)
UPDATE public.mml_commands c
SET target_paths = r.paths,
    tree_node_refs = r.paths,
    updated_at = NOW()
FROM refreshed r
WHERE c.id = r.id;

WITH object_paths(command_code, object_path) AS (
    VALUES
        ('ADD 5G_CELL', 'Device.Services.FAPService.{i}.CellConfig.LTE.RAN.NeighborList.5GCell.'),
        ('RMV 5G_CELL', 'Device.Services.FAPService.{i}.CellConfig.LTE.RAN.NeighborList.5GCell.'),
        ('ADD INTER_RAT_CELL_NR', 'Device.Services.FAPService.{i}.CellConfig.LTE.RAN.NeighborList.InterRATCell.NR.'),
        ('RMV INTER_RAT_CELL_NR', 'Device.Services.FAPService.{i}.CellConfig.LTE.RAN.NeighborList.InterRATCell.NR.'),
        ('ADD INTER_RAT_CELL_UMTS', 'Device.Services.FAPService.{i}.CellConfig.LTE.RAN.NeighborList.InterRATCell.UMTS.'),
        ('RMV INTER_RAT_CELL_UMTS', 'Device.Services.FAPService.{i}.CellConfig.LTE.RAN.NeighborList.InterRATCell.UMTS.'),
        ('ADD INTER_RAT_CELL_GSM', 'Device.Services.FAPService.{i}.CellConfig.LTE.RAN.NeighborList.InterRATCell.GSM.'),
        ('RMV INTER_RAT_CELL_GSM', 'Device.Services.FAPService.{i}.CellConfig.LTE.RAN.NeighborList.InterRATCell.GSM.'),
        ('ADD LTE_CELL', 'Device.Services.FAPService.{i}.CellConfig.LTE.RAN.NeighborList.LTECell.'),
        ('RMV LTE_CELL', 'Device.Services.FAPService.{i}.CellConfig.LTE.RAN.NeighborList.LTECell.'),
        ('ADD LTE_CELL', 'Device.Services.FAPService.{i}.CellConfig.{i}.LTE.RAN.NeighborList.LTECell.'),
        ('RMV LTE_CELL', 'Device.Services.FAPService.{i}.CellConfig.{i}.LTE.RAN.NeighborList.LTECell.')
), merged AS (
    SELECT
        c.id,
        jsonb_agg(DISTINCT path_value ORDER BY path_value) AS paths
    FROM public.mml_commands c
    JOIN object_paths op ON op.command_code = c.command_code
    CROSS JOIN LATERAL (
        SELECT jsonb_array_elements_text(c.target_paths) AS path_value
        UNION
        SELECT op.object_path
    ) p
    WHERE c.deprecated_at IS NULL
    GROUP BY c.id
)
UPDATE public.mml_commands c
SET target_paths = m.paths,
    tree_node_refs = m.paths,
    updated_at = NOW()
FROM merged m
WHERE c.id = m.id;

COMMIT;
-- END NeighborList coverage under neighbor cell parameter group

-- BEGIN NeighborList duplicate operation cleanup
BEGIN;

WITH si_group AS (
    SELECT id
    FROM public.mml_command_groups
    WHERE group_code = 'chapter:SI'
      AND param_version = 'cmcc-td-lte-v2.3'
      AND deleted_at IS NULL
    ORDER BY updated_at DESC
    LIMIT 1
), desired_commands(command_code, command_name_zh, command_name_en, logical_name_zh, logical_name_en, operation_type, rpc_method, target_object) AS (
    VALUES
        ('ADD NR_CELL', '新增 5G邻区参数管理', 'Add 5G Neighbor Parameter Management', '5G邻区参数管理', '5G Neighbor Parameter Management', 'ADD', 'AddObject', 'Device.Services.FAPService.CellConfig.NR.RAN.NeighborList.NRCell.'),
        ('RMV NR_CELL', '删除 5G邻区参数管理', 'Remove 5G Neighbor Parameter Management', '5G邻区参数管理', '5G Neighbor Parameter Management', 'RMV', 'DeleteObject', 'Device.Services.FAPService.CellConfig.NR.RAN.NeighborList.NRCell.')
)
INSERT INTO public.mml_commands (
    command_name, command_code, category, description, rpc_method, target_paths,
    target_object, group_id, command_name_i18n, require_confirm, confirm_msg_i18n,
    operation_type, logical_name_i18n, source, catalog_protected, platform_tags,
    deprecated_at, tree_node_refs, instance_range_meta, help_doc, notes
)
SELECT
    d.command_name_zh,
    d.command_code,
    'neighbor-list-coverage',
    'NR RAN NeighborList multi-instance operation restored for MML neighbor cell group',
    d.rpc_method,
    jsonb_build_array(d.target_object),
    d.target_object,
    g.id,
    jsonb_build_object('zh-CN', d.command_name_zh, 'en-US', d.command_name_en),
    false,
    '{}'::jsonb,
    d.operation_type,
    jsonb_build_object('zh-CN', d.logical_name_zh, 'en-US', d.logical_name_en),
    'standard',
    true,
    '{}'::jsonb,
    NULL,
    jsonb_build_array(d.target_object),
    '[]'::jsonb,
    '',
    ''
FROM desired_commands d
CROSS JOIN si_group g
ON CONFLICT (command_code) DO UPDATE
SET command_name = EXCLUDED.command_name,
    category = EXCLUDED.category,
    description = EXCLUDED.description,
    rpc_method = EXCLUDED.rpc_method,
    target_object = EXCLUDED.target_object,
    group_id = EXCLUDED.group_id,
    command_name_i18n = EXCLUDED.command_name_i18n,
    operation_type = EXCLUDED.operation_type,
    logical_name_i18n = EXCLUDED.logical_name_i18n,
    source = EXCLUDED.source,
    catalog_protected = EXCLUDED.catalog_protected,
    deprecated_at = NULL,
    updated_at = NOW();

WITH source_fields AS (
    SELECT
        sf.mml_code,
        sf.label_i18n,
        sf.default_selected,
        sf.sort_order,
        sf.standard_path_id,
        sf.access_type,
        sf.is_supported
    FROM public.mml_commands c
    JOIN public.mml_command_sub_fields sf ON sf.command_id = c.id AND sf.deprecated_at IS NULL
    WHERE c.command_code = 'LST SI_SUB_05'
      AND c.deprecated_at IS NULL
), target_cmds AS (
    SELECT id, operation_type
    FROM public.mml_commands
    WHERE command_code IN ('ADD NR_CELL', 'RMV NR_CELL')
      AND deprecated_at IS NULL
)
INSERT INTO public.mml_command_sub_fields (
    command_id, mml_code, label_i18n, default_selected, is_required,
    sort_order, standard_path_id, access_type, is_supported
)
SELECT
    t.id,
    sf.mml_code,
    sf.label_i18n,
    sf.default_selected,
    t.operation_type = 'ADD',
    sf.sort_order,
    sf.standard_path_id,
    sf.access_type,
    sf.is_supported
FROM target_cmds t
CROSS JOIN source_fields sf
ON CONFLICT (command_id, standard_path_id) DO UPDATE
SET mml_code = EXCLUDED.mml_code,
    label_i18n = EXCLUDED.label_i18n,
    default_selected = EXCLUDED.default_selected,
    is_required = EXCLUDED.is_required,
    sort_order = EXCLUDED.sort_order,
    access_type = EXCLUDED.access_type,
    is_supported = EXCLUDED.is_supported,
    deprecated_at = NULL,
    updated_at = NOW();

WITH target_cmds AS (
    SELECT id
    FROM public.mml_commands
    WHERE command_code IN ('ADD NR_CELL', 'RMV NR_CELL')
), refreshed AS (
    SELECT
        t.id,
        COALESCE(jsonb_agg(sp.standard_path ORDER BY sf.sort_order, sp.standard_path)
                 FILTER (WHERE sp.standard_path IS NOT NULL), '[]'::jsonb) AS paths
    FROM target_cmds t
    LEFT JOIN public.mml_command_sub_fields sf ON sf.command_id = t.id AND sf.deprecated_at IS NULL
    LEFT JOIN public.standard_params sp ON sp.id = sf.standard_path_id
    GROUP BY t.id
), object_paths(command_code, object_path) AS (
    VALUES
        ('ADD NR_CELL', 'Device.Services.FAPService.{i}.CellConfig.{i}.NR.RAN.NeighborList.NRCell.'),
        ('RMV NR_CELL', 'Device.Services.FAPService.{i}.CellConfig.{i}.NR.RAN.NeighborList.NRCell.')
), merged AS (
    SELECT
        c.id,
        jsonb_agg(DISTINCT path_value ORDER BY path_value) AS paths
    FROM public.mml_commands c
    JOIN refreshed r ON r.id = c.id
    LEFT JOIN object_paths op ON op.command_code = c.command_code
    CROSS JOIN LATERAL (
        SELECT jsonb_array_elements_text(r.paths) AS path_value
        UNION
        SELECT op.object_path
        WHERE op.object_path IS NOT NULL
    ) p
    GROUP BY c.id
)
UPDATE public.mml_commands c
SET target_paths = m.paths,
    tree_node_refs = m.paths,
    updated_at = NOW()
FROM merged m
WHERE c.id = m.id;

-- The SI_SUB_01..05 ADD/RMV commands are zero-field AddObject/DeleteObject shells.
-- ADD/RMV 5G_CELL is also hidden because its parameters are covered by the
-- NR neighbor parameter management command set, and showing it creates an
-- extra business name in the neighbor command tree.
-- Keep LST/MOD SI_SUB_* for parameter management, and use the object-specific
-- ADD/RMV commands above for multi-instance neighbor add/delete.
UPDATE public.mml_commands
SET deprecated_at = NOW(),
    updated_at = NOW()
WHERE command_code IN (
    'ADD 5G_CELL', 'RMV 5G_CELL',
    'ADD SI_SUB_01', 'RMV SI_SUB_01',
    'ADD SI_SUB_02', 'RMV SI_SUB_02',
    'ADD SI_SUB_03', 'RMV SI_SUB_03',
    'ADD SI_SUB_04', 'RMV SI_SUB_04',
    'ADD SI_SUB_05', 'RMV SI_SUB_05'
)
  AND deprecated_at IS NULL;

COMMIT;
-- END NeighborList duplicate operation cleanup

-- BEGIN NeighborList command name normalization
BEGIN;

WITH desired_names(command_code, command_name_zh, command_name_en, logical_name_zh, logical_name_en) AS (
    VALUES
        ('ADD INTER_RAT_CELL_NR', '新增 NR邻区参数管理', 'Add NR Neighbor Parameter Management', 'NR邻区参数管理', 'NR Neighbor Parameter Management'),
        ('RMV INTER_RAT_CELL_NR', '删除 NR邻区参数管理', 'Remove NR Neighbor Parameter Management', 'NR邻区参数管理', 'NR Neighbor Parameter Management'),
        ('ADD LTE_CELL', '新增 LTE邻区参数管理', 'Add LTE Neighbor Parameter Management', 'LTE邻区参数管理', 'LTE Neighbor Parameter Management'),
        ('RMV LTE_CELL', '删除 LTE邻区参数管理', 'Remove LTE Neighbor Parameter Management', 'LTE邻区参数管理', 'LTE Neighbor Parameter Management'),
        ('ADD INTER_RAT_CELL_UMTS', '新增 TD邻区参数管理', 'Add TD Neighbor Parameter Management', 'TD邻区参数管理', 'TD Neighbor Parameter Management'),
        ('RMV INTER_RAT_CELL_UMTS', '删除 TD邻区参数管理', 'Remove TD Neighbor Parameter Management', 'TD邻区参数管理', 'TD Neighbor Parameter Management'),
        ('ADD INTER_RAT_CELL_GSM', '新增 GSM邻区参数管理', 'Add GSM Neighbor Parameter Management', 'GSM邻区参数管理', 'GSM Neighbor Parameter Management'),
        ('RMV INTER_RAT_CELL_GSM', '删除 GSM邻区参数管理', 'Remove GSM Neighbor Parameter Management', 'GSM邻区参数管理', 'GSM Neighbor Parameter Management'),
        ('ADD NR_CELL', '新增 5G邻区参数管理', 'Add 5G Neighbor Parameter Management', '5G邻区参数管理', '5G Neighbor Parameter Management'),
        ('RMV NR_CELL', '删除 5G邻区参数管理', 'Remove 5G Neighbor Parameter Management', '5G邻区参数管理', '5G Neighbor Parameter Management')
)
UPDATE public.mml_commands c
SET command_name = d.command_name_zh,
    command_name_i18n = jsonb_build_object('zh-CN', d.command_name_zh, 'en-US', d.command_name_en),
    logical_name_i18n = jsonb_build_object('zh-CN', d.logical_name_zh, 'en-US', d.logical_name_en),
    updated_at = NOW()
FROM desired_names d
WHERE c.command_code = d.command_code;

COMMIT;
-- END NeighborList command name normalization

-- BEGIN FAP DNS and LAN business grouping
BEGIN;

WITH desired_dns AS (
    SELECT
        '15b0b31b-7ad1-4ad8-9dc3-7f18a05d0470'::uuid AS id,
        'MML350_G_DNS_CONFIG'::varchar AS group_code,
        'DNS配置'::varchar AS group_name_zh,
        'DNS Configuration'::varchar AS group_name_en,
        'MML350_G_DNS_CONFIG'::ltree AS path,
        15 AS display_order,
        '{"zh-CN":"DNS配置","en-US":"DNS Configuration"}'::jsonb AS name_i18n
)
INSERT INTO public.mml_command_groups (
    id, group_code, group_name_zh, group_name_en, path, param_version,
    display_order, is_active, name_i18n, source, catalog_protected, chapter_code
)
SELECT id, group_code, group_name_zh, group_name_en, path, 'cmcc-td-lte-v2.3',
       display_order, true, name_i18n, 'admin', false, NULL
FROM desired_dns
ON CONFLICT (param_version, group_code) DO UPDATE
SET group_name_zh = EXCLUDED.group_name_zh,
    group_name_en = EXCLUDED.group_name_en,
    path = EXCLUDED.path,
    display_order = EXCLUDED.display_order,
    is_active = true,
    name_i18n = EXCLUDED.name_i18n,
    source = EXCLUDED.source,
    catalog_protected = EXCLUDED.catalog_protected,
    chapter_code = EXCLUDED.chapter_code,
    deleted_at = NULL,
    deprecated_at = NULL,
    updated_at = NOW();

UPDATE public.mml_command_groups
SET group_name_zh = 'LAN口配置',
    group_name_en = 'LAN Port Configuration',
    name_i18n = '{"zh-CN":"LAN口配置","en-US":"LAN Port Configuration"}'::jsonb,
    updated_at = NOW()
WHERE param_version = 'cmcc-td-lte-v2.3'
  AND group_code = 'MML350_G_DEVICE_FAP';

WITH groups AS (
    SELECT
        (SELECT id FROM public.mml_command_groups WHERE param_version='cmcc-td-lte-v2.3' AND group_code='MML350_G_DNS_CONFIG' AND deleted_at IS NULL LIMIT 1) AS dns_group_id,
        (SELECT id FROM public.mml_command_groups WHERE param_version='cmcc-td-lte-v2.3' AND group_code='MML350_G_DEVICE_FAP' AND deleted_at IS NULL LIMIT 1) AS lan_group_id
), dns_lst AS (
    UPDATE public.mml_commands c
    SET group_id = groups.dns_group_id,
        command_name = '查询 DNS',
        command_name_i18n = '{"zh-CN":"查询 DNS","en-US":"Query DNS"}'::jsonb,
        logical_name_i18n = '{"zh-CN":"DNS","en-US":"DNS"}'::jsonb,
        deprecated_at = NULL,
        updated_at = NOW()
    FROM groups
    WHERE c.command_code = 'LST MML350_DEVICE_FAP__GNB_CONFIG'
    RETURNING c.id, c.category, c.description, c.target_paths, groups.dns_group_id
), dns_mod AS (
    INSERT INTO public.mml_commands (
        command_name, command_code, category, description, rpc_method,
        target_paths, group_id, command_name_i18n, require_confirm,
        confirm_msg_i18n, operation_type, logical_name_i18n, source,
        catalog_protected, platform_tags, tree_node_refs
    )
    SELECT
        '修改 DNS',
        'MOD MML350_DEVICE_FAP__GNB_CONFIG',
        category,
        description,
        'SetParameterValues',
        target_paths,
        dns_group_id,
        '{"zh-CN":"修改 DNS","en-US":"Modify DNS"}'::jsonb,
        false,
        '{}'::jsonb,
        'MOD',
        '{"zh-CN":"DNS","en-US":"DNS"}'::jsonb,
        'admin',
        false,
        '{}'::jsonb,
        target_paths
    FROM dns_lst
    ON CONFLICT (command_code) DO UPDATE
    SET command_name = EXCLUDED.command_name,
        category = EXCLUDED.category,
        description = EXCLUDED.description,
        rpc_method = EXCLUDED.rpc_method,
        target_paths = EXCLUDED.target_paths,
        group_id = EXCLUDED.group_id,
        command_name_i18n = EXCLUDED.command_name_i18n,
        operation_type = EXCLUDED.operation_type,
        logical_name_i18n = EXCLUDED.logical_name_i18n,
        tree_node_refs = EXCLUDED.tree_node_refs,
        deprecated_at = NULL,
        updated_at = NOW()
    RETURNING id
), dns_fields AS (
    INSERT INTO public.mml_command_sub_fields (
        command_id, mml_code, label_i18n, default_selected, is_required,
        sort_order, standard_path_id, access_type, is_supported
    )
    SELECT
        dns_mod.id,
        sf.mml_code,
        sf.label_i18n,
        sf.default_selected,
        sf.is_required,
        sf.sort_order,
        sf.standard_path_id,
        'RW',
        sf.is_supported
    FROM dns_mod
    JOIN dns_lst ON true
    JOIN public.mml_command_sub_fields sf ON sf.command_id = dns_lst.id AND sf.deprecated_at IS NULL AND sf.access_type = 'RW'
    ON CONFLICT (command_id, standard_path_id) DO UPDATE
    SET mml_code = EXCLUDED.mml_code,
        label_i18n = EXCLUDED.label_i18n,
        default_selected = EXCLUDED.default_selected,
        is_required = EXCLUDED.is_required,
        sort_order = EXCLUDED.sort_order,
        access_type = EXCLUDED.access_type,
        is_supported = EXCLUDED.is_supported,
        deprecated_at = NULL,
        updated_at = NOW()
    RETURNING 1
)
UPDATE public.mml_commands c
SET group_id = groups.lan_group_id,
    command_name = CASE c.command_code
        WHEN 'LST MML350_DEVICE_FAP__LANCONFIG' THEN '查询 LAN口配置'
        WHEN 'MOD MML350_DEVICE_FAP__LANCONFIG' THEN '修改 LAN口配置'
        ELSE c.command_name
    END,
    command_name_i18n = CASE c.command_code
        WHEN 'LST MML350_DEVICE_FAP__LANCONFIG' THEN '{"zh-CN":"查询 LAN口配置","en-US":"Query LAN Port Configuration"}'::jsonb
        WHEN 'MOD MML350_DEVICE_FAP__LANCONFIG' THEN '{"zh-CN":"修改 LAN口配置","en-US":"Modify LAN Port Configuration"}'::jsonb
        ELSE c.command_name_i18n
    END,
    logical_name_i18n = '{"zh-CN":"LAN口配置","en-US":"LAN Port Configuration"}'::jsonb,
    deprecated_at = NULL,
    updated_at = NOW()
FROM groups
WHERE c.command_code IN ('LST MML350_DEVICE_FAP__LANCONFIG', 'MOD MML350_DEVICE_FAP__LANCONFIG');

WITH target_cmds AS (
    SELECT id, command_code, operation_type
    FROM public.mml_commands
    WHERE command_code IN ('LST MML350_DEVICE_FAP__GNB_CONFIG', 'MOD MML350_DEVICE_FAP__GNB_CONFIG')
      AND deprecated_at IS NULL
), max_sort AS (
    SELECT
        t.id AS command_id,
        COALESCE(
            MAX(sf.sort_order) FILTER (
                WHERE sp.standard_path IS NULL
                   OR sp.standard_path NOT LIKE 'Device.DeviceInfo.HOST_CONFIG_DNS%'
                  AND sp.standard_path <> 'Device.DeviceInfo.DNS_CONFIG_IPMODE'
            ),
            0
        ) AS base_sort
    FROM target_cmds t
    LEFT JOIN public.mml_command_sub_fields sf ON sf.command_id = t.id AND sf.deprecated_at IS NULL
    LEFT JOIN public.standard_params sp ON sp.id = sf.standard_path_id
    GROUP BY t.id
), host_dns_paths AS (
    SELECT
        sp.id AS standard_path_id,
        sp.standard_path,
        upper(regexp_replace(replace(sp.standard_path, 'Device.DeviceInfo.', ''), '[^A-Za-z0-9]+', '_', 'g')) AS mml_code,
        row_number() OVER (ORDER BY sp.standard_path) AS path_order
    FROM public.standard_params sp
    WHERE sp.standard_path LIKE 'Device.DeviceInfo.HOST_CONFIG_DNS%'
       OR sp.standard_path = 'Device.DeviceInfo.DNS_CONFIG_IPMODE'
)
INSERT INTO public.mml_command_sub_fields (
    command_id, mml_code, label_i18n, default_selected, is_required,
    sort_order, standard_path_id, access_type, is_supported
)
SELECT
    t.id,
    p.mml_code,
    jsonb_build_object('zh-CN', p.mml_code, 'en-US', initcap(replace(lower(p.mml_code), '_', ' '))),
    true,
    t.operation_type = 'MOD',
    ms.base_sort + p.path_order,
    p.standard_path_id,
    'RW',
    true
FROM target_cmds t
JOIN max_sort ms ON ms.command_id = t.id
CROSS JOIN host_dns_paths p
ON CONFLICT (command_id, standard_path_id) DO UPDATE
SET mml_code = EXCLUDED.mml_code,
    label_i18n = EXCLUDED.label_i18n,
    default_selected = EXCLUDED.default_selected,
    is_required = EXCLUDED.is_required,
    sort_order = EXCLUDED.sort_order,
    access_type = EXCLUDED.access_type,
    is_supported = EXCLUDED.is_supported,
    deprecated_at = NULL,
    updated_at = NOW();

WITH target_cmds AS (
    SELECT id
    FROM public.mml_commands
    WHERE command_code IN ('LST MML350_DEVICE_FAP__GNB_CONFIG', 'MOD MML350_DEVICE_FAP__GNB_CONFIG')
), refreshed AS (
    SELECT
        t.id,
        COALESCE(jsonb_agg(sp.standard_path ORDER BY sf.sort_order, sp.standard_path)
                 FILTER (WHERE sp.standard_path IS NOT NULL), '[]'::jsonb) AS paths
    FROM target_cmds t
    LEFT JOIN public.mml_command_sub_fields sf ON sf.command_id = t.id AND sf.deprecated_at IS NULL
    LEFT JOIN public.standard_params sp ON sp.id = sf.standard_path_id
    GROUP BY t.id
)
UPDATE public.mml_commands c
SET target_paths = r.paths,
    tree_node_refs = r.paths,
    updated_at = NOW()
FROM refreshed r
WHERE c.id = r.id;

WITH target_cmds AS (
    SELECT id, command_code, operation_type
    FROM public.mml_commands
    WHERE command_code IN ('LST MML350_DEVICE_FAP__LANCONFIG', 'MOD MML350_DEVICE_FAP__LANCONFIG')
      AND deprecated_at IS NULL
), max_sort AS (
    SELECT
        t.id AS command_id,
        COALESCE(
            MAX(sf.sort_order) FILTER (
                WHERE sp.standard_path IS NULL
                   OR sp.standard_path NOT LIKE 'Device.DeviceInfo.LAN_CONFIG_%'
            ),
            0
        ) AS base_sort
    FROM target_cmds t
    LEFT JOIN public.mml_command_sub_fields sf ON sf.command_id = t.id AND sf.deprecated_at IS NULL
    LEFT JOIN public.standard_params sp ON sp.id = sf.standard_path_id
    GROUP BY t.id
), lan_config_paths AS (
    SELECT
        sp.id AS standard_path_id,
        sp.standard_path,
        upper(regexp_replace(replace(sp.standard_path, 'Device.DeviceInfo.', ''), '[^A-Za-z0-9]+', '_', 'g')) AS mml_code,
        row_number() OVER (ORDER BY sp.standard_path) AS path_order
    FROM public.standard_params sp
    WHERE sp.standard_path LIKE 'Device.DeviceInfo.LAN_CONFIG_%'
)
INSERT INTO public.mml_command_sub_fields (
    command_id, mml_code, label_i18n, default_selected, is_required,
    sort_order, standard_path_id, access_type, is_supported
)
SELECT
    t.id,
    p.mml_code,
    jsonb_build_object('zh-CN', p.mml_code, 'en-US', initcap(replace(lower(p.mml_code), '_', ' '))),
    true,
    t.operation_type = 'MOD',
    ms.base_sort + p.path_order,
    p.standard_path_id,
    'RW',
    true
FROM target_cmds t
JOIN max_sort ms ON ms.command_id = t.id
CROSS JOIN lan_config_paths p
ON CONFLICT (command_id, standard_path_id) DO UPDATE
SET mml_code = EXCLUDED.mml_code,
    label_i18n = EXCLUDED.label_i18n,
    default_selected = EXCLUDED.default_selected,
    is_required = EXCLUDED.is_required,
    sort_order = EXCLUDED.sort_order,
    access_type = EXCLUDED.access_type,
    is_supported = EXCLUDED.is_supported,
    deprecated_at = NULL,
    updated_at = NOW();

WITH target_cmds AS (
    SELECT id
    FROM public.mml_commands
    WHERE command_code IN ('LST MML350_DEVICE_FAP__LANCONFIG', 'MOD MML350_DEVICE_FAP__LANCONFIG')
), refreshed AS (
    SELECT
        t.id,
        COALESCE(jsonb_agg(sp.standard_path ORDER BY sf.sort_order, sp.standard_path)
                 FILTER (WHERE sp.standard_path IS NOT NULL), '[]'::jsonb) AS paths
    FROM target_cmds t
    LEFT JOIN public.mml_command_sub_fields sf ON sf.command_id = t.id AND sf.deprecated_at IS NULL
    LEFT JOIN public.standard_params sp ON sp.id = sf.standard_path_id
    GROUP BY t.id
)
UPDATE public.mml_commands c
SET target_paths = r.paths,
    tree_node_refs = r.paths,
    updated_at = NOW()
FROM refreshed r
WHERE c.id = r.id;

-- Object deletion commands should not expose parameter sub-fields. DeleteObject
-- only consumes target_object plus the selected instance index; keep the object
-- path in target_paths/tree_node_refs for filtering and display.
UPDATE public.mml_command_sub_fields sf
SET deprecated_at = COALESCE(sf.deprecated_at, NOW()),
    updated_at = NOW()
FROM public.mml_commands c
WHERE c.id = sf.command_id
  AND c.operation_type = 'RMV'
  AND c.deprecated_at IS NULL
  AND sf.deprecated_at IS NULL
  AND COALESCE(c.target_object, '') <> '';

UPDATE public.mml_commands c
SET target_paths = jsonb_build_array(c.target_object),
    tree_node_refs = jsonb_build_array(c.target_object),
    updated_at = NOW()
WHERE c.operation_type = 'RMV'
  AND c.deprecated_at IS NULL
  AND COALESCE(c.target_object, '') <> '';

COMMIT;
-- END FAP DNS and LAN business grouping

-- BEGIN duplicate Device.IP IPv4Address cleanup
BEGIN;

UPDATE public.mml_commands
SET deprecated_at = NOW(),
    updated_at = NOW()
WHERE command_code IN ('LST MML350_DEVICE_IP__IPV4ADDRESS', 'MOD MML350_DEVICE_IP__IPV4ADDRESS');

DELETE FROM public.mml_command_groups g
WHERE g.param_version = 'cmcc-td-lte-v2.3'
  AND g.group_code = 'MML350_G_DEVICE_IP'
  AND NOT EXISTS (
      SELECT 1
      FROM public.mml_commands c
      WHERE c.group_id = g.id
        AND c.deprecated_at IS NULL
  );

COMMIT;
-- END duplicate Device.IP IPv4Address cleanup

-- BEGIN WAN IPv4Address Device.IP parameter merge
BEGIN;

WITH target_cmds AS (
    UPDATE public.mml_commands c
    SET command_name = CASE c.command_code
            WHEN 'LST INTERFACE_I_PV4_ADDRESS' THEN '查询 IPv4地址配置'
            WHEN 'MOD INTERFACE_I_PV4_ADDRESS' THEN '修改 IPv4地址配置'
            ELSE c.command_name
        END,
        command_name_i18n = CASE c.command_code
            WHEN 'LST INTERFACE_I_PV4_ADDRESS' THEN '{"zh-CN":"查询 IPv4地址配置","en-US":"Query IPv4 Address Configuration"}'::jsonb
            WHEN 'MOD INTERFACE_I_PV4_ADDRESS' THEN '{"zh-CN":"修改 IPv4地址配置","en-US":"Modify IPv4 Address Configuration"}'::jsonb
            ELSE c.command_name_i18n
        END,
        logical_name_i18n = '{"zh-CN":"IPv4地址配置","en-US":"IPv4 Address Configuration"}'::jsonb,
        deprecated_at = NULL,
        updated_at = NOW()
    WHERE c.command_code IN ('LST INTERFACE_I_PV4_ADDRESS', 'MOD INTERFACE_I_PV4_ADDRESS')
    RETURNING c.id
), source_paths AS (
    SELECT *
    FROM (VALUES
        ('ADDRESSINGTYPE', 'ADDRESSINGTYPE', 'AddressingType', 'Device.IP.Interface.{i}.IPv4Address.{i}.AddressingType', 10),
        ('DEFAULTGATEWAY', 'DEFAULTGATEWAY', 'DefaultGateway', 'Device.IP.Interface.{i}.IPv4Address.{i}.DefaultGateway', 11),
        ('IPADDRESS', 'IPADDRESS', 'IPAddress', 'Device.IP.Interface.{i}.IPv4Address.{i}.IPAddress', 12),
        ('SUBNETMASK', 'SUBNETMASK', 'SubnetMask', 'Device.IP.Interface.{i}.IPv4Address.{i}.SubnetMask', 13)
    ) AS v(mml_code, label_zh, label_en, standard_path, sort_order)
), to_insert AS (
    SELECT
        t.id AS command_id,
        ('DEVICE_IP_' || s.mml_code)::varchar(100) AS mml_code,
        jsonb_build_object('zh-CN', s.label_zh, 'en-US', s.label_en) AS label_i18n,
        true AS default_selected,
        false AS is_required,
        s.sort_order,
        sp.id AS standard_path_id,
        'RW'::varchar AS access_type,
        true AS is_supported
    FROM target_cmds t
    CROSS JOIN source_paths s
    JOIN public.standard_params sp ON sp.standard_path = s.standard_path
)
INSERT INTO public.mml_command_sub_fields (
    command_id, mml_code, label_i18n, default_selected, is_required,
    sort_order, standard_path_id, access_type, is_supported
)
SELECT command_id, mml_code, label_i18n, default_selected, is_required,
       sort_order, standard_path_id, access_type, is_supported
FROM to_insert
ON CONFLICT (command_id, standard_path_id) DO UPDATE
SET mml_code = EXCLUDED.mml_code,
    label_i18n = EXCLUDED.label_i18n,
    default_selected = EXCLUDED.default_selected,
    is_required = EXCLUDED.is_required,
    sort_order = EXCLUDED.sort_order,
    access_type = EXCLUDED.access_type,
    is_supported = EXCLUDED.is_supported,
    deprecated_at = NULL,
    updated_at = NOW();

COMMIT;
-- END WAN IPv4Address Device.IP parameter merge

-- BEGIN IPsec FAP parameter merge
BEGIN;

WITH target_pairs(source_code, target_code) AS (
    VALUES
        ('LST MML350_DEVICE_FAP__IPSEC', 'LST SM_SUB_01'),
        ('MOD MML350_DEVICE_FAP__IPSEC', 'MOD SM_SUB_01')
), target_cmds AS (
    SELECT src.id AS source_id, dst.id AS target_id
    FROM target_pairs p
    JOIN public.mml_commands src ON src.command_code = p.source_code
    JOIN public.mml_commands dst ON dst.command_code = p.target_code AND dst.deprecated_at IS NULL
), max_sort AS (
    SELECT tc.target_id, COALESCE(MAX(sf.sort_order), 0) AS base_sort
    FROM target_cmds tc
    LEFT JOIN public.mml_command_sub_fields sf ON sf.command_id = tc.target_id AND sf.deprecated_at IS NULL
    GROUP BY tc.target_id
), source_fields AS (
    SELECT
        tc.target_id,
        sf.mml_code,
        sf.label_i18n,
        sf.default_selected,
        sf.is_required,
        ms.base_sort + row_number() OVER (PARTITION BY tc.target_id ORDER BY sf.sort_order, sp.standard_path) AS sort_order,
        sf.standard_path_id,
        sf.access_type,
        sf.is_supported,
        sp.standard_path,
        count(*) OVER (PARTITION BY tc.target_id, sf.mml_code) AS source_mml_count
    FROM target_cmds tc
    JOIN max_sort ms ON ms.target_id = tc.target_id
    JOIN public.mml_command_sub_fields sf ON sf.command_id = tc.source_id AND sf.deprecated_at IS NULL
    JOIN public.standard_params sp ON sp.id = sf.standard_path_id
)
INSERT INTO public.mml_command_sub_fields (
    command_id, mml_code, label_i18n, default_selected, is_required,
    sort_order, standard_path_id, access_type, is_supported
)
SELECT
    target_id,
    CASE
        WHEN source_mml_count > 1 THEN LEFT('FAP_' || UPPER(regexp_replace(replace(standard_path, 'Device.FAP.', ''), '[^A-Za-z0-9]+', '_', 'g')), 100)
        ELSE LEFT('FAP_' || mml_code, 100)
    END,
    label_i18n,
    default_selected,
    is_required,
    sort_order,
    standard_path_id,
    access_type,
    is_supported
FROM source_fields
ON CONFLICT (command_id, standard_path_id) DO UPDATE
SET mml_code = EXCLUDED.mml_code,
    label_i18n = EXCLUDED.label_i18n,
    default_selected = EXCLUDED.default_selected,
    is_required = EXCLUDED.is_required,
    sort_order = EXCLUDED.sort_order,
    access_type = EXCLUDED.access_type,
    is_supported = EXCLUDED.is_supported,
    deprecated_at = NULL,
    updated_at = NOW();

UPDATE public.mml_commands
SET deprecated_at = NOW(),
    updated_at = NOW()
WHERE command_code IN ('LST MML350_DEVICE_FAP__IPSEC', 'MOD MML350_DEVICE_FAP__IPSEC');

COMMIT;
-- END IPsec FAP parameter merge

-- BEGIN GSM Bts command regrouping
BEGIN;

WITH gsm_group AS (
    SELECT id
    FROM public.mml_command_groups
    WHERE param_version = 'cmcc-td-lte-v2.3'
      AND group_code = 'MML350_G_DEVICEGSM'
      AND deleted_at IS NULL
    ORDER BY updated_at DESC
    LIMIT 1
), desired_commands(command_code, command_name_zh, command_name_en, logical_name_zh, logical_name_en, display_order) AS (
    VALUES
        ('LST MML350_DEVICEGSM__BTS_TRX', '查询Bts.Trx', 'Query Bts.Trx', 'Bts.Trx', 'Bts.Trx', 33),
        ('LST MML350_DEVICEGSM__BTS_TRX_TS', '查询Bts.Trx.Ts', 'Query Bts.Trx.Ts', 'Bts.Trx.Ts', 'Bts.Trx.Ts', 34)
)
INSERT INTO public.mml_commands (
    command_name, command_code, category, description, rpc_method, target_paths,
    target_object, group_id, command_name_i18n, require_confirm, confirm_msg_i18n,
    operation_type, logical_name_i18n, source, catalog_protected, platform_tags,
    deprecated_at, tree_node_refs, instance_range_meta, help_doc, notes
)
SELECT
    d.command_name_zh,
    d.command_code,
    'mml-350-20260704',
    'DeviceGSM.Bts multi-instance subcommands split from LST MML350_DEVICEGSM__BTS',
    'GetParameterValues',
    '[]'::jsonb,
    '',
    g.id,
    jsonb_build_object('zh-CN', d.command_name_zh, 'en-US', d.command_name_en),
    false,
    '{}'::jsonb,
    'LST',
    jsonb_build_object('zh-CN', d.logical_name_zh, 'en-US', d.logical_name_en),
    'admin',
    false,
    '{}'::jsonb,
    NULL,
    '[]'::jsonb,
    '[]'::jsonb,
    '',
    ''
FROM desired_commands d
CROSS JOIN gsm_group g
ON CONFLICT (command_code) DO UPDATE
SET command_name = EXCLUDED.command_name,
    category = EXCLUDED.category,
    description = EXCLUDED.description,
    rpc_method = EXCLUDED.rpc_method,
    target_object = EXCLUDED.target_object,
    group_id = EXCLUDED.group_id,
    command_name_i18n = EXCLUDED.command_name_i18n,
    operation_type = EXCLUDED.operation_type,
    logical_name_i18n = EXCLUDED.logical_name_i18n,
    source = EXCLUDED.source,
    deprecated_at = NULL,
    updated_at = NOW();

WITH bts_source AS (
    SELECT id
    FROM public.mml_commands
    WHERE command_code = 'LST MML350_DEVICEGSM__BTS'
), bts_paths AS (
    SELECT
        sf.mml_code AS old_mml_code,
        sf.label_i18n,
        sf.default_selected,
        sf.is_required,
        sf.standard_path_id,
        sf.access_type,
        sf.is_supported,
        sp.standard_path,
        CASE
            WHEN sp.standard_path LIKE 'DeviceGSM.Bts.{i}.Trx.{i}.Ts.{i}.%' THEN 'LST MML350_DEVICEGSM__BTS_TRX_TS'
            WHEN sp.standard_path = 'DeviceGSM.Bts.Trx.Index'
              OR sp.standard_path LIKE 'DeviceGSM.Bts.{i}.Trx.{i}.%' THEN 'LST MML350_DEVICEGSM__BTS_TRX'
            ELSE 'LST MML350_DEVICE_SERVICES__GSMBTSCELLDT'
        END AS target_code
    FROM bts_source src
    JOIN public.mml_command_sub_fields sf ON sf.command_id = src.id
    JOIN public.standard_params sp ON sp.id = sf.standard_path_id
    WHERE sf.deprecated_at IS NULL
      AND sp.standard_path LIKE 'DeviceGSM.Bts.%'
), numbered AS (
    SELECT
        bp.*,
        row_number() OVER (PARTITION BY bp.target_code ORDER BY bp.standard_path) AS target_order
    FROM bts_paths bp
), target_rows AS (
    SELECT
        dst.id AS command_id,
        CASE
            WHEN n.target_code = 'LST MML350_DEVICE_SERVICES__GSMBTSCELLDT'
                THEN LEFT('BTS_' || UPPER(regexp_replace(replace(replace(n.standard_path, 'DeviceGSM.Bts.{i}.', ''), 'DeviceGSM.Bts.', ''), '[^A-Za-z0-9]+', '_', 'g')), 100)
            WHEN n.target_code = 'LST MML350_DEVICEGSM__BTS_TRX'
                THEN LEFT('BTS_TRX_' || UPPER(regexp_replace(replace(replace(n.standard_path, 'DeviceGSM.Bts.{i}.Trx.{i}.', ''), 'DeviceGSM.Bts.Trx.', ''), '[^A-Za-z0-9]+', '_', 'g')), 100)
            ELSE LEFT('BTS_TRX_TS_' || UPPER(regexp_replace(replace(n.standard_path, 'DeviceGSM.Bts.{i}.Trx.{i}.Ts.{i}.', ''), '[^A-Za-z0-9]+', '_', 'g')), 100)
        END AS mml_code,
        n.label_i18n,
        n.default_selected,
        n.is_required,
        CASE
            WHEN n.target_code = 'LST MML350_DEVICE_SERVICES__GSMBTSCELLDT' THEN 1000 + n.target_order
            ELSE n.target_order
        END AS sort_order,
        n.standard_path_id,
        n.access_type,
        n.is_supported
    FROM numbered n
    JOIN public.mml_commands dst ON dst.command_code = n.target_code
)
INSERT INTO public.mml_command_sub_fields (
    command_id, mml_code, label_i18n, default_selected, is_required,
    sort_order, standard_path_id, access_type, is_supported
)
SELECT
    command_id, mml_code, label_i18n, default_selected, is_required,
    sort_order, standard_path_id, access_type, is_supported
FROM target_rows
ON CONFLICT (command_id, standard_path_id) DO UPDATE
SET mml_code = EXCLUDED.mml_code,
    label_i18n = EXCLUDED.label_i18n,
    default_selected = EXCLUDED.default_selected,
    is_required = EXCLUDED.is_required,
    sort_order = EXCLUDED.sort_order,
    access_type = EXCLUDED.access_type,
    is_supported = EXCLUDED.is_supported,
    deprecated_at = NULL,
    updated_at = NOW();

WITH bts_source AS (
    SELECT id
    FROM public.mml_commands
    WHERE command_code = 'LST MML350_DEVICEGSM__BTS'
)
DELETE FROM public.mml_command_sub_fields sf
USING bts_source src, public.standard_params sp
WHERE sf.command_id = src.id
  AND sp.id = sf.standard_path_id
  AND sp.standard_path LIKE 'DeviceGSM.Bts.%';

UPDATE public.mml_commands
SET deprecated_at = NOW(),
    target_paths = '[]'::jsonb,
    tree_node_refs = '[]'::jsonb,
    updated_at = NOW()
WHERE command_code = 'LST MML350_DEVICEGSM__BTS';

WITH target_cmds AS (
    SELECT id
    FROM public.mml_commands
    WHERE command_code IN (
        'LST MML350_DEVICE_SERVICES__GSMBTSCELLDT',
        'LST MML350_DEVICEGSM__BTS_TRX',
        'LST MML350_DEVICEGSM__BTS_TRX_TS'
    )
), refreshed AS (
    SELECT
        t.id,
        COALESCE(jsonb_agg(sp.standard_path ORDER BY sf.sort_order, sp.standard_path)
                 FILTER (WHERE sp.standard_path IS NOT NULL), '[]'::jsonb) AS paths
    FROM target_cmds t
    LEFT JOIN public.mml_command_sub_fields sf ON sf.command_id = t.id AND sf.deprecated_at IS NULL
    LEFT JOIN public.standard_params sp ON sp.id = sf.standard_path_id
    GROUP BY t.id
)
UPDATE public.mml_commands c
SET target_paths = r.paths,
    tree_node_refs = r.paths,
    updated_at = NOW()
FROM refreshed r
WHERE c.id = r.id;

COMMIT;
-- END GSM Bts command regrouping

-- BEGIN GSM object-boundary correction
BEGIN;

WITH gsm_group AS (
    SELECT id
    FROM public.mml_command_groups
    WHERE param_version = 'cmcc-td-lte-v2.3'
      AND group_code = 'MML350_G_DEVICEGSM'
      AND deleted_at IS NULL
    ORDER BY updated_at DESC
    LIMIT 1
)
UPDATE public.mml_commands c
SET group_id = g.id,
    command_name = '查询BTS小区',
    command_name_i18n = '{"zh-CN":"查询BTS小区","en-US":"Query BTS Cells"}'::jsonb,
    logical_name_i18n = '{"zh-CN":"BTS小区","en-US":"BTS Cells"}'::jsonb,
    target_object = 'DeviceGSM.Bts.',
    deprecated_at = NULL,
    updated_at = NOW()
FROM gsm_group g
WHERE c.command_code = 'LST MML350_DEVICEGSM__BTS'
  AND c.source = 'admin';

UPDATE public.mml_commands
SET target_object = CASE command_code
        WHEN 'LST MML350_DEVICE_SERVICES__GSMBTSCELLDT' THEN 'Device.Services.GsmBTSCellDT.{i}.'
        WHEN 'LST MML350_DEVICEGSM__BTS_TRX' THEN 'DeviceGSM.Bts.{i}.Trx.{i}.'
        WHEN 'LST MML350_DEVICEGSM__BTS_TRX_TS' THEN 'DeviceGSM.Bts.{i}.Trx.{i}.Ts.{i}.'
        WHEN 'LST MML350_DEVICEGSM__CS7INSTANCE' THEN 'DeviceGSM.Cs7Instance.{i}.'
        WHEN 'LST MML350_DEVICEGSM__CS7INSTANCE_AS' THEN 'DeviceGSM.Cs7Instance.{i}.As.{i}.'
        WHEN 'LST MML350_DEVICEGSM__CS7INSTANCE_ASP' THEN 'DeviceGSM.Cs7Instance.{i}.Asp.{i}.'
        WHEN 'LST MML350_DEVICEGSM__CS7INSTANCE_SCCPADDR' THEN 'DeviceGSM.Cs7Instance.{i}.SccpAddr.{i}.'
        WHEN 'LST MML350_DEVICEGSM__MGW' THEN 'DeviceGSM.Mgw.{i}.'
        WHEN 'LST MML350_DEVICEGSM__MSC' THEN 'DeviceGSM.Msc.{i}.'
        ELSE target_object
    END,
    command_name = CASE command_code
        WHEN 'LST MML350_DEVICEGSM__BTS_TRX' THEN '查询Bts.Trx'
        WHEN 'LST MML350_DEVICEGSM__BTS_TRX_TS' THEN '查询Bts.Trx.Ts'
        WHEN 'LST MML350_DEVICEGSM__CS7INSTANCE' THEN '查询Cs7Instance'
        WHEN 'LST MML350_DEVICEGSM__CS7INSTANCE_AS' THEN '查询Cs7Instance.As'
        WHEN 'LST MML350_DEVICEGSM__CS7INSTANCE_ASP' THEN '查询Cs7Instance.Asp'
        WHEN 'LST MML350_DEVICEGSM__CS7INSTANCE_SCCPADDR' THEN '查询Cs7Instance.SccpAddr'
        WHEN 'LST MML350_DEVICEGSM__MGW' THEN '查询Mgw'
        WHEN 'LST MML350_DEVICEGSM__MSC' THEN '查询Msc'
        ELSE command_name
    END,
    command_name_i18n = CASE command_code
        WHEN 'LST MML350_DEVICEGSM__BTS_TRX' THEN '{"zh-CN":"查询Bts.Trx","en-US":"Query Bts.Trx"}'::jsonb
        WHEN 'LST MML350_DEVICEGSM__BTS_TRX_TS' THEN '{"zh-CN":"查询Bts.Trx.Ts","en-US":"Query Bts.Trx.Ts"}'::jsonb
        WHEN 'LST MML350_DEVICEGSM__CS7INSTANCE' THEN '{"zh-CN":"查询Cs7Instance","en-US":"Query Cs7Instance"}'::jsonb
        WHEN 'LST MML350_DEVICEGSM__CS7INSTANCE_AS' THEN '{"zh-CN":"查询Cs7Instance.As","en-US":"Query Cs7Instance.As"}'::jsonb
        WHEN 'LST MML350_DEVICEGSM__CS7INSTANCE_ASP' THEN '{"zh-CN":"查询Cs7Instance.Asp","en-US":"Query Cs7Instance.Asp"}'::jsonb
        WHEN 'LST MML350_DEVICEGSM__CS7INSTANCE_SCCPADDR' THEN '{"zh-CN":"查询Cs7Instance.SccpAddr","en-US":"Query Cs7Instance.SccpAddr"}'::jsonb
        WHEN 'LST MML350_DEVICEGSM__MGW' THEN '{"zh-CN":"查询Mgw","en-US":"Query Mgw"}'::jsonb
        WHEN 'LST MML350_DEVICEGSM__MSC' THEN '{"zh-CN":"查询Msc","en-US":"Query Msc"}'::jsonb
        ELSE command_name_i18n
    END,
    logical_name_i18n = CASE command_code
        WHEN 'LST MML350_DEVICEGSM__BTS_TRX' THEN '{"zh-CN":"Bts.Trx","en-US":"Bts.Trx"}'::jsonb
        WHEN 'LST MML350_DEVICEGSM__BTS_TRX_TS' THEN '{"zh-CN":"Bts.Trx.Ts","en-US":"Bts.Trx.Ts"}'::jsonb
        WHEN 'LST MML350_DEVICEGSM__CS7INSTANCE' THEN '{"zh-CN":"Cs7Instance","en-US":"Cs7Instance"}'::jsonb
        WHEN 'LST MML350_DEVICEGSM__CS7INSTANCE_AS' THEN '{"zh-CN":"Cs7Instance.As","en-US":"Cs7Instance.As"}'::jsonb
        WHEN 'LST MML350_DEVICEGSM__CS7INSTANCE_ASP' THEN '{"zh-CN":"Cs7Instance.Asp","en-US":"Cs7Instance.Asp"}'::jsonb
        WHEN 'LST MML350_DEVICEGSM__CS7INSTANCE_SCCPADDR' THEN '{"zh-CN":"Cs7Instance.SccpAddr","en-US":"Cs7Instance.SccpAddr"}'::jsonb
        WHEN 'LST MML350_DEVICEGSM__MGW' THEN '{"zh-CN":"Mgw","en-US":"Mgw"}'::jsonb
        WHEN 'LST MML350_DEVICEGSM__MSC' THEN '{"zh-CN":"Msc","en-US":"Msc"}'::jsonb
        ELSE logical_name_i18n
    END,
    updated_at = NOW()
WHERE command_code IN (
    'LST MML350_DEVICE_SERVICES__GSMBTSCELLDT',
    'LST MML350_DEVICEGSM__BTS_TRX',
    'LST MML350_DEVICEGSM__BTS_TRX_TS',
    'LST MML350_DEVICEGSM__CS7INSTANCE',
    'LST MML350_DEVICEGSM__CS7INSTANCE_AS',
    'LST MML350_DEVICEGSM__CS7INSTANCE_ASP',
    'LST MML350_DEVICEGSM__CS7INSTANCE_SCCPADDR',
    'LST MML350_DEVICEGSM__MGW',
    'LST MML350_DEVICEGSM__MSC'
);

WITH source_fields AS (
    SELECT DISTINCT ON (sp.standard_path)
        sp.id AS standard_path_id,
        sp.standard_path,
        sf.label_i18n,
        sf.default_selected,
        sf.is_required,
        sf.access_type,
        sf.is_supported
    FROM public.standard_params sp
    LEFT JOIN public.mml_command_sub_fields sf ON sf.standard_path_id = sp.id
    LEFT JOIN public.mml_commands c ON c.id = sf.command_id
    WHERE sp.standard_path LIKE 'DeviceGSM.Bts.%'
      AND sp.standard_path <> 'DeviceGSM.Bts.Trx.Index'
      AND sp.standard_path NOT LIKE 'DeviceGSM.Bts.{i}.Trx.{i}.%'
    ORDER BY sp.standard_path,
             CASE WHEN c.command_code = 'LST MML350_DEVICEGSM__BTS' THEN 0
                  WHEN c.command_code = 'LST MML350_DEVICE_SERVICES__GSMBTSCELLDT' THEN 1
                  ELSE 2
             END
), numbered AS (
    SELECT
        sf.*,
        row_number() OVER (ORDER BY sf.standard_path) AS sort_order
    FROM source_fields sf
), target_cmd AS (
    SELECT id
    FROM public.mml_commands
    WHERE command_code = 'LST MML350_DEVICEGSM__BTS'
)
INSERT INTO public.mml_command_sub_fields (
    command_id, mml_code, label_i18n, default_selected, is_required,
    sort_order, standard_path_id, access_type, is_supported
)
SELECT
    t.id,
    LEFT('BTS_' || UPPER(regexp_replace(replace(replace(n.standard_path, 'DeviceGSM.Bts.{i}.', ''), 'DeviceGSM.Bts.', ''), '[^A-Za-z0-9]+', '_', 'g')), 100),
    COALESCE(n.label_i18n, jsonb_build_object('zh-CN', upper(regexp_replace(n.standard_path, '^.*\.', '')), 'en-US', upper(regexp_replace(n.standard_path, '^.*\.', '')))),
    COALESCE(n.default_selected, true),
    COALESCE(n.is_required, false),
    n.sort_order,
    n.standard_path_id,
    COALESCE(n.access_type, 'RO'),
    COALESCE(n.is_supported, true)
FROM numbered n
CROSS JOIN target_cmd t
ON CONFLICT (command_id, standard_path_id) DO UPDATE
SET mml_code = EXCLUDED.mml_code,
    label_i18n = EXCLUDED.label_i18n,
    default_selected = EXCLUDED.default_selected,
    is_required = EXCLUDED.is_required,
    sort_order = EXCLUDED.sort_order,
    access_type = EXCLUDED.access_type,
    is_supported = EXCLUDED.is_supported,
    deprecated_at = NULL,
    updated_at = NOW();

WITH gsm_cmd AS (
    SELECT id
    FROM public.mml_commands
    WHERE command_code = 'LST MML350_DEVICE_SERVICES__GSMBTSCELLDT'
), bts_cmd AS (
    SELECT id
    FROM public.mml_commands
    WHERE command_code = 'LST MML350_DEVICEGSM__BTS'
)
DELETE FROM public.mml_command_sub_fields sf
USING public.standard_params sp
WHERE sp.id = sf.standard_path_id
  AND (
      (sf.command_id IN (SELECT id FROM gsm_cmd) AND sp.standard_path LIKE 'DeviceGSM.Bts.%')
      OR
      (sf.command_id IN (SELECT id FROM bts_cmd) AND (
          sp.standard_path = 'DeviceGSM.Bts.Trx.Index'
          OR sp.standard_path LIKE 'DeviceGSM.Bts.{i}.Trx.{i}.%'
      ))
  );

WITH target_cmds AS (
    SELECT id
    FROM public.mml_commands
    WHERE command_code IN (
        'LST MML350_DEVICE_SERVICES__GSMBTSCELLDT',
        'LST MML350_DEVICEGSM__BTS',
        'LST MML350_DEVICEGSM__BTS_TRX',
        'LST MML350_DEVICEGSM__BTS_TRX_TS',
        'LST MML350_DEVICEGSM__CS7INSTANCE',
        'LST MML350_DEVICEGSM__CS7INSTANCE_AS',
        'LST MML350_DEVICEGSM__CS7INSTANCE_ASP',
        'LST MML350_DEVICEGSM__CS7INSTANCE_SCCPADDR',
        'LST MML350_DEVICEGSM__MGW',
        'LST MML350_DEVICEGSM__MSC'
    )
), refreshed AS (
    SELECT
        t.id,
        COALESCE(jsonb_agg(sp.standard_path ORDER BY sf.sort_order, sp.standard_path)
                 FILTER (WHERE sp.standard_path IS NOT NULL), '[]'::jsonb) AS paths
    FROM target_cmds t
    LEFT JOIN public.mml_command_sub_fields sf ON sf.command_id = t.id AND sf.deprecated_at IS NULL
    LEFT JOIN public.standard_params sp ON sp.id = sf.standard_path_id
    GROUP BY t.id
)
UPDATE public.mml_commands c
SET target_paths = r.paths,
    tree_node_refs = r.paths,
    updated_at = NOW()
FROM refreshed r
WHERE c.id = r.id;

COMMIT;
-- END GSM object-boundary correction

-- BEGIN GSM writable and multi-instance operations
BEGIN;

WITH rw_lst AS (
    SELECT
        c.id AS lst_id,
        c.command_code AS lst_code,
        replace(c.command_code, 'LST ', 'MOD ') AS mod_code,
        c.category,
        c.description,
        c.group_id,
        c.logical_name_i18n,
        COALESCE(c.logical_name_i18n->>'zh-CN', c.command_name) AS logical_zh,
        COALESCE(c.logical_name_i18n->>'en-US', c.command_name) AS logical_en,
        jsonb_agg(to_jsonb(sp.standard_path) ORDER BY sf.sort_order, sp.standard_path) AS target_paths
    FROM public.mml_commands c
    JOIN public.mml_command_sub_fields sf ON sf.command_id = c.id AND sf.deprecated_at IS NULL AND sf.access_type = 'RW'
    JOIN public.standard_params sp ON sp.id = sf.standard_path_id
    WHERE c.operation_type = 'LST'
      AND c.deprecated_at IS NULL
      AND c.command_code IN (
          'LST MML350_DEVICE_SERVICES__GSMBTSCELLDT',
          'LST MML350_DEVICEGSM__BTS',
          'LST MML350_DEVICEGSM__BTS_TRX',
          'LST MML350_DEVICEGSM__BTS_TRX_TS',
          'LST MML350_DEVICEGSM__CS7INSTANCE',
          'LST MML350_DEVICEGSM__CS7INSTANCE_AS',
          'LST MML350_DEVICEGSM__CS7INSTANCE_ASP',
          'LST MML350_DEVICEGSM__CS7INSTANCE_SCCPADDR',
          'LST MML350_DEVICEGSM__MGW',
          'LST MML350_DEVICEGSM__MSC'
      )
    GROUP BY c.id, c.command_code, c.category, c.description, c.group_id, c.logical_name_i18n, c.command_name
), upserted_mod AS (
    INSERT INTO public.mml_commands (
        command_name, command_code, category, description, rpc_method,
        target_paths, target_object, group_id, command_name_i18n, require_confirm,
        confirm_msg_i18n, operation_type, logical_name_i18n, source,
        catalog_protected, platform_tags, tree_node_refs
    )
    SELECT
        '修改' || logical_zh,
        mod_code,
        category,
        description,
        'SetParameterValues',
        target_paths,
        '',
        group_id,
        jsonb_build_object('zh-CN', '修改' || logical_zh, 'en-US', 'Modify ' || logical_en),
        false,
        '{}'::jsonb,
        'MOD',
        logical_name_i18n,
        'admin',
        false,
        '{}'::jsonb,
        target_paths
    FROM rw_lst
    ON CONFLICT (command_code) DO UPDATE
    SET command_name = EXCLUDED.command_name,
        category = EXCLUDED.category,
        description = EXCLUDED.description,
        rpc_method = EXCLUDED.rpc_method,
        target_paths = EXCLUDED.target_paths,
        target_object = EXCLUDED.target_object,
        group_id = EXCLUDED.group_id,
        command_name_i18n = EXCLUDED.command_name_i18n,
        operation_type = EXCLUDED.operation_type,
        logical_name_i18n = EXCLUDED.logical_name_i18n,
        tree_node_refs = EXCLUDED.tree_node_refs,
        deprecated_at = NULL,
        updated_at = NOW()
    RETURNING id, command_code
)
INSERT INTO public.mml_command_sub_fields (
    command_id, mml_code, label_i18n, default_selected, is_required,
    sort_order, standard_path_id, access_type, is_supported
)
SELECT
    u.id,
    sf.mml_code,
    sf.label_i18n,
    sf.default_selected,
    sf.is_required,
    sf.sort_order,
    sf.standard_path_id,
    'RW',
    sf.is_supported
FROM rw_lst r
JOIN public.mml_command_sub_fields sf ON sf.command_id = r.lst_id AND sf.deprecated_at IS NULL AND sf.access_type = 'RW'
JOIN upserted_mod u ON u.command_code = r.mod_code
ON CONFLICT (command_id, standard_path_id) DO UPDATE
SET mml_code = EXCLUDED.mml_code,
    label_i18n = EXCLUDED.label_i18n,
    default_selected = EXCLUDED.default_selected,
    is_required = EXCLUDED.is_required,
    sort_order = EXCLUDED.sort_order,
    access_type = EXCLUDED.access_type,
    is_supported = EXCLUDED.is_supported,
    deprecated_at = NULL,
    updated_at = NOW();

WITH multi_lst AS (
    SELECT
        c.command_code,
        c.category,
        c.description,
        c.group_id,
        c.logical_name_i18n,
        COALESCE(c.logical_name_i18n->>'zh-CN', c.command_name) AS logical_zh,
        COALESCE(c.logical_name_i18n->>'en-US', c.command_name) AS logical_en,
        c.target_object,
        CASE
            WHEN c.target_object LIKE '%.{i}.' THEN regexp_replace(c.target_object, '\.\{i\}\.$', '.')
            ELSE c.target_object
        END AS rpc_object,
        jsonb_build_array(c.target_object) AS target_paths
    FROM public.mml_commands c
    WHERE c.operation_type = 'LST'
      AND c.deprecated_at IS NULL
      AND c.command_code IN (
          'LST MML350_DEVICE_SERVICES__GSMBTSCELLDT',
          'LST MML350_DEVICEGSM__BTS',
          'LST MML350_DEVICEGSM__BTS_TRX',
          'LST MML350_DEVICEGSM__BTS_TRX_TS',
          'LST MML350_DEVICEGSM__CS7INSTANCE',
          'LST MML350_DEVICEGSM__CS7INSTANCE_AS',
          'LST MML350_DEVICEGSM__CS7INSTANCE_ASP',
          'LST MML350_DEVICEGSM__CS7INSTANCE_SCCPADDR',
          'LST MML350_DEVICEGSM__MGW',
          'LST MML350_DEVICEGSM__MSC'
      )
      AND c.target_object IS NOT NULL
      AND c.target_object <> ''
), desired_ops AS (
    SELECT
        op.operation_type,
        op.rpc_method,
        op.zh_prefix,
        op.en_prefix,
        replace(m.command_code, 'LST ', op.operation_type || ' ') AS command_code,
        m.category,
        m.description,
        m.group_id,
        m.logical_name_i18n,
        m.logical_zh,
        m.logical_en,
        m.rpc_object,
        m.target_paths
    FROM multi_lst m
    CROSS JOIN (VALUES
        ('ADD', 'AddObject', '新增', 'Add'),
        ('RMV', 'DeleteObject', '删除', 'Delete')
    ) AS op(operation_type, rpc_method, zh_prefix, en_prefix)
)
INSERT INTO public.mml_commands (
    command_name, command_code, category, description, rpc_method,
    target_paths, target_object, group_id, command_name_i18n, require_confirm,
    confirm_msg_i18n, operation_type, logical_name_i18n, source,
    catalog_protected, platform_tags, tree_node_refs
)
SELECT
    zh_prefix || logical_zh,
    command_code,
    category,
    description,
    rpc_method,
    target_paths,
    rpc_object,
    group_id,
    jsonb_build_object('zh-CN', zh_prefix || logical_zh, 'en-US', en_prefix || ' ' || logical_en),
    false,
    '{}'::jsonb,
    operation_type,
    logical_name_i18n,
    'admin',
    false,
    '{}'::jsonb,
    target_paths
FROM desired_ops
ON CONFLICT (command_code) DO UPDATE
SET command_name = EXCLUDED.command_name,
    category = EXCLUDED.category,
    description = EXCLUDED.description,
    rpc_method = EXCLUDED.rpc_method,
    target_paths = EXCLUDED.target_paths,
    target_object = EXCLUDED.target_object,
    group_id = EXCLUDED.group_id,
    command_name_i18n = EXCLUDED.command_name_i18n,
    operation_type = EXCLUDED.operation_type,
    logical_name_i18n = EXCLUDED.logical_name_i18n,
    tree_node_refs = EXCLUDED.tree_node_refs,
    deprecated_at = NULL,
    updated_at = NOW();

COMMIT;
-- END GSM writable and multi-instance operations

-- BEGIN GSM single-leaf command consolidation
BEGIN;

WITH gsm_group AS (
    SELECT id
    FROM public.mml_command_groups
    WHERE param_version = 'cmcc-td-lte-v2.3'
      AND group_code = 'MML350_G_DEVICEGSM'
      AND deleted_at IS NULL
    ORDER BY updated_at DESC
    LIMIT 1
)
INSERT INTO public.mml_commands (
    command_name, command_code, category, description, rpc_method, target_paths,
    target_object, group_id, command_name_i18n, require_confirm, confirm_msg_i18n,
    operation_type, logical_name_i18n, source, catalog_protected, platform_tags,
    deprecated_at, tree_node_refs, instance_range_meta, help_doc, notes
)
SELECT
    '查询GSM全局参数',
    'LST MML350_DEVICEGSM__GLOBAL',
    'mml-350-20260704',
    'Consolidated DeviceGSM single-leaf query command',
    'GetParameterValues',
    '[]'::jsonb,
    'DeviceGSM.',
    g.id,
    '{"zh-CN":"查询GSM全局参数","en-US":"Query GSM Global Parameters"}'::jsonb,
    false,
    '{}'::jsonb,
    'LST',
    '{"zh-CN":"GSM全局参数","en-US":"GSM Global Parameters"}'::jsonb,
    'admin',
    false,
    '{}'::jsonb,
    NULL,
    '[]'::jsonb,
    '[]'::jsonb,
    '',
    ''
FROM gsm_group g
ON CONFLICT (command_code) DO UPDATE
SET command_name = EXCLUDED.command_name,
    category = EXCLUDED.category,
    description = EXCLUDED.description,
    rpc_method = EXCLUDED.rpc_method,
    target_object = EXCLUDED.target_object,
    group_id = EXCLUDED.group_id,
    command_name_i18n = EXCLUDED.command_name_i18n,
    operation_type = EXCLUDED.operation_type,
    logical_name_i18n = EXCLUDED.logical_name_i18n,
    source = EXCLUDED.source,
    deprecated_at = NULL,
    updated_at = NOW();

WITH source_fields AS (
    SELECT DISTINCT ON (sp.standard_path)
        sp.id AS standard_path_id,
        sp.standard_path,
        sf.mml_code,
        sf.label_i18n,
        sf.default_selected,
        sf.is_required,
        sf.access_type,
        sf.is_supported
    FROM public.standard_params sp
    LEFT JOIN public.mml_command_sub_fields sf ON sf.standard_path_id = sp.id
    LEFT JOIN public.mml_commands c ON c.id = sf.command_id
    WHERE sp.standard_path ~ '^DeviceGSM\.[^.]+$'
    ORDER BY sp.standard_path,
             CASE WHEN c.command_code = 'LST MML350_DEVICEGSM__GLOBAL' THEN 0
                  WHEN c.command_code LIKE 'LST MML350_DEVICEGSM__%' THEN 1
                  ELSE 2
             END
), numbered AS (
    SELECT
        sf.*,
        row_number() OVER (ORDER BY sf.standard_path) AS sort_order
    FROM source_fields sf
), target_cmd AS (
    SELECT id
    FROM public.mml_commands
    WHERE command_code = 'LST MML350_DEVICEGSM__GLOBAL'
)
INSERT INTO public.mml_command_sub_fields (
    command_id, mml_code, label_i18n, default_selected, is_required,
    sort_order, standard_path_id, access_type, is_supported
)
SELECT
    t.id,
    LEFT('GSM_' || UPPER(regexp_replace(replace(n.standard_path, 'DeviceGSM.', ''), '[^A-Za-z0-9]+', '_', 'g')), 100),
    COALESCE(n.label_i18n, jsonb_build_object('zh-CN', upper(replace(n.standard_path, 'DeviceGSM.', '')), 'en-US', upper(replace(n.standard_path, 'DeviceGSM.', '')))),
    COALESCE(n.default_selected, true),
    COALESCE(n.is_required, false),
    n.sort_order,
    n.standard_path_id,
    COALESCE(n.access_type, 'RO'),
    COALESCE(n.is_supported, true)
FROM numbered n
CROSS JOIN target_cmd t
ON CONFLICT (command_id, standard_path_id) DO UPDATE
SET mml_code = EXCLUDED.mml_code,
    label_i18n = EXCLUDED.label_i18n,
    default_selected = EXCLUDED.default_selected,
    is_required = EXCLUDED.is_required,
    sort_order = EXCLUDED.sort_order,
    access_type = EXCLUDED.access_type,
    is_supported = EXCLUDED.is_supported,
    deprecated_at = NULL,
    updated_at = NOW();

WITH leaf_commands AS (
    SELECT DISTINCT c.id
    FROM public.mml_commands c
    JOIN public.mml_command_sub_fields sf ON sf.command_id = c.id AND sf.deprecated_at IS NULL
    JOIN public.standard_params sp ON sp.id = sf.standard_path_id
    WHERE c.command_code <> 'LST MML350_DEVICEGSM__GLOBAL'
      AND c.operation_type = 'LST'
      AND c.command_code LIKE 'LST MML350_DEVICEGSM__%'
      AND sp.standard_path ~ '^DeviceGSM\.[^.]+$'
      AND NOT EXISTS (
          SELECT 1
          FROM public.mml_command_sub_fields sf2
          JOIN public.standard_params sp2 ON sp2.id = sf2.standard_path_id
          WHERE sf2.command_id = c.id
            AND sf2.deprecated_at IS NULL
            AND sp2.standard_path !~ '^DeviceGSM\.[^.]+$'
      )
)
UPDATE public.mml_commands c
SET deprecated_at = NOW(),
    target_paths = '[]'::jsonb,
    tree_node_refs = '[]'::jsonb,
    updated_at = NOW()
FROM leaf_commands lc
WHERE c.id = lc.id;

WITH target_cmd AS (
    SELECT id
    FROM public.mml_commands
    WHERE command_code = 'LST MML350_DEVICEGSM__GLOBAL'
), refreshed AS (
    SELECT
        t.id,
        COALESCE(jsonb_agg(sp.standard_path ORDER BY sf.sort_order, sp.standard_path)
                 FILTER (WHERE sp.standard_path IS NOT NULL), '[]'::jsonb) AS paths
    FROM target_cmd t
    LEFT JOIN public.mml_command_sub_fields sf ON sf.command_id = t.id AND sf.deprecated_at IS NULL
    LEFT JOIN public.standard_params sp ON sp.id = sf.standard_path_id
    GROUP BY t.id
)
UPDATE public.mml_commands c
SET target_paths = r.paths,
    tree_node_refs = r.paths,
    updated_at = NOW()
FROM refreshed r
WHERE c.id = r.id;

COMMIT;
-- END GSM single-leaf command consolidation

-- BEGIN DeviceInfo SignallingTrace grouping
BEGIN;

WITH desired_group AS (
    SELECT
        'a4894949-ebb5-44c7-8905-4d7460326408'::uuid AS id,
        'MML_DEVICEINFO_SIGNALLING_TRACE'::varchar AS group_code,
        '信令跟踪'::varchar AS group_name_zh,
        'Signalling Trace'::varchar AS group_name_en,
        'MML_DEVICEINFO_SIGNALLING_TRACE'::ltree AS path,
        11 AS display_order,
        '{"zh-CN":"信令跟踪","en-US":"Signalling Trace"}'::jsonb AS name_i18n
)
INSERT INTO public.mml_command_groups (
    id, group_code, group_name_zh, group_name_en, path, param_version,
    display_order, is_active, name_i18n, source, catalog_protected, chapter_code
)
SELECT id, group_code, group_name_zh, group_name_en, path, 'cmcc-td-lte-v2.3',
       display_order, true, name_i18n, 'admin', false, 'SA'
FROM desired_group
ON CONFLICT (param_version, group_code) DO UPDATE
SET group_name_zh = EXCLUDED.group_name_zh,
    group_name_en = EXCLUDED.group_name_en,
    path = EXCLUDED.path,
    display_order = EXCLUDED.display_order,
    is_active = true,
    name_i18n = EXCLUDED.name_i18n,
    source = EXCLUDED.source,
    catalog_protected = EXCLUDED.catalog_protected,
    chapter_code = EXCLUDED.chapter_code,
    deleted_at = NULL,
    deprecated_at = NULL,
    updated_at = NOW();

WITH group_row AS (
    SELECT id
    FROM public.mml_command_groups
    WHERE param_version = 'cmcc-td-lte-v2.3'
      AND group_code = 'MML_DEVICEINFO_SIGNALLING_TRACE'
      AND deleted_at IS NULL
    LIMIT 1
), paths AS (
    SELECT jsonb_agg(to_jsonb(standard_path) ORDER BY standard_path) AS target_paths
    FROM public.standard_params
    WHERE standard_path LIKE 'Device.DeviceInfo.SignallingTrace.%'
), desired_commands(command_code, command_name, command_name_en, rpc_method, operation_type) AS (
    VALUES
        ('LST SIGNALLING_TRACE', '查询信令跟踪', 'Query Signalling Trace', 'GetParameterValues', 'LST'),
        ('MOD SIGNALLING_TRACE', '修改信令跟踪', 'Modify Signalling Trace', 'SetParameterValues', 'MOD')
)
INSERT INTO public.mml_commands (
    command_name, command_code, category, description, rpc_method,
    target_paths, target_object, group_id, command_name_i18n, require_confirm,
    confirm_msg_i18n, operation_type, logical_name_i18n, source,
    catalog_protected, platform_tags, tree_node_refs
)
SELECT
    d.command_name,
    d.command_code,
    '3',
    'DeviceInfo SignallingTrace parameters',
    d.rpc_method,
    COALESCE(p.target_paths, '[]'::jsonb),
    CASE WHEN d.operation_type = 'LST' THEN 'Device.DeviceInfo.SignallingTrace.' ELSE '' END,
    g.id,
    jsonb_build_object('zh-CN', d.command_name, 'en-US', d.command_name_en),
    false,
    '{}'::jsonb,
    d.operation_type,
    '{"zh-CN":"信令跟踪","en-US":"Signalling Trace"}'::jsonb,
    'admin',
    false,
    '{}'::jsonb,
    COALESCE(p.target_paths, '[]'::jsonb)
FROM desired_commands d
CROSS JOIN group_row g
CROSS JOIN paths p
ON CONFLICT (command_code) DO UPDATE
SET command_name = EXCLUDED.command_name,
    category = EXCLUDED.category,
    description = EXCLUDED.description,
    rpc_method = EXCLUDED.rpc_method,
    target_paths = EXCLUDED.target_paths,
    target_object = EXCLUDED.target_object,
    group_id = EXCLUDED.group_id,
    command_name_i18n = EXCLUDED.command_name_i18n,
    operation_type = EXCLUDED.operation_type,
    logical_name_i18n = EXCLUDED.logical_name_i18n,
    source = EXCLUDED.source,
    tree_node_refs = EXCLUDED.tree_node_refs,
    deprecated_at = NULL,
    updated_at = NOW();

WITH target_cmds AS (
    SELECT id, operation_type
    FROM public.mml_commands
    WHERE command_code IN ('LST SIGNALLING_TRACE', 'MOD SIGNALLING_TRACE')
), source_paths AS (
    SELECT
        id AS standard_path_id,
        standard_path,
        upper(regexp_replace(replace(standard_path, 'Device.DeviceInfo.SignallingTrace.', ''), '[^A-Za-z0-9]+', '_', 'g')) AS mml_code,
        row_number() OVER (ORDER BY standard_path) AS sort_order,
        CASE WHEN access = 'READ_WRITE' THEN 'RW' ELSE 'RO' END AS access_type
    FROM public.standard_params
    WHERE standard_path LIKE 'Device.DeviceInfo.SignallingTrace.%'
)
INSERT INTO public.mml_command_sub_fields (
    command_id, mml_code, label_i18n, default_selected, is_required,
    sort_order, standard_path_id, access_type, is_supported
)
SELECT
    t.id,
    p.mml_code,
    jsonb_build_object('zh-CN', p.mml_code, 'en-US', initcap(replace(lower(p.mml_code), '_', ' '))),
    true,
    t.operation_type = 'MOD',
    p.sort_order,
    p.standard_path_id,
    CASE WHEN t.operation_type = 'MOD' THEN 'RW' ELSE p.access_type END,
    true
FROM target_cmds t
CROSS JOIN source_paths p
WHERE t.operation_type = 'LST'
   OR (t.operation_type = 'MOD' AND p.access_type = 'RW')
ON CONFLICT (command_id, standard_path_id) DO UPDATE
SET mml_code = EXCLUDED.mml_code,
    label_i18n = EXCLUDED.label_i18n,
    default_selected = EXCLUDED.default_selected,
    is_required = EXCLUDED.is_required,
    sort_order = EXCLUDED.sort_order,
    access_type = EXCLUDED.access_type,
    is_supported = EXCLUDED.is_supported,
    deprecated_at = NULL,
    updated_at = NOW();

-- Put NR log commands directly under 日志参数管理.
WITH log_defs(group_code, logical_name_zh, logical_name_en, path_prefix) AS (
    VALUES
        ('SE_RRM_LOG', 'RRM日志管理', 'RRM Log Management', 'Device.Services.FAPService.{i}.CellConfig.{i}.NR.RrmLogConfig.'),
        ('SE_DUMGR_LOG', 'DUMGR日志管理', 'DUMGR Log Management', 'Device.Services.FAPService.{i}.FAPControl.NR.DumgrProvLog.'),
        ('SE_RLC_LOG', 'RLC日志管理', 'RLC Log Management', 'Device.Services.FAPService.{i}.FAPControl.NR.RlcLog.'),
        ('SE_RRC_LOG', 'RRC日志管理', 'RRC Log Management', 'Device.Services.FAPService.{i}.FAPControl.NR.RrcProv.'),
        ('SE_MAC_LOG', 'MAC日志管理', 'MAC Log Management', 'Device.Services.FAPService.{i}.CellConfig.{i}.NR.MacSchedulerInfo.'),
        ('SE_OTHER_LOG', '其他日志管理', 'Other Log Management', 'Device.Services.FAPService.{i}.FAPControl.NR.F1apLog.'),
        ('SE_OTHER_LOG', '其他日志管理', 'Other Log Management', 'Device.Services.FAPService.{i}.FAPControl.NR.GtpuLog.'),
        ('SE_OTHER_LOG', '其他日志管理', 'Other Log Management', 'Device.Services.FAPService.{i}.FAPControl.NR.PdcpLog.'),
        ('SE_OTHER_LOG', '其他日志管理', 'Other Log Management', 'Device.Services.FAPService.{i}.CellConfig.{i}.NR.Duf1uLog.')
), logical_defs AS (
    SELECT DISTINCT group_code, logical_name_zh, logical_name_en
    FROM log_defs
), group_rows AS (
    SELECT g.id
    FROM public.mml_command_groups g
    WHERE g.group_code = 'chapter:SE'
      AND g.param_version = 'cmcc-td-lte-v2.3'
      AND g.deleted_at IS NULL
), desired_commands AS (
    SELECT
        op.operation_type || ' ' || d.group_code AS command_code,
        CASE op.operation_type WHEN 'LST' THEN '查询 ' ELSE '修改 ' END || d.logical_name_zh AS command_name_zh,
        CASE op.operation_type WHEN 'LST' THEN 'Query ' ELSE 'Modify ' END || d.logical_name_en AS command_name_en,
        op.operation_type,
        d.logical_name_zh,
        d.logical_name_en,
        CASE op.operation_type WHEN 'LST' THEN 'GetParameterValues' ELSE 'SetParameterValues' END AS rpc_method,
        gr.id AS group_id
    FROM logical_defs d
    CROSS JOIN group_rows gr
    CROSS JOIN (VALUES ('LST'), ('MOD')) AS op(operation_type)
), command_paths AS (
    SELECT
        dc.command_code,
        COALESCE(jsonb_agg(to_jsonb(sp.standard_path) ORDER BY sp.standard_path), '[]'::jsonb) AS target_paths
    FROM desired_commands dc
    JOIN log_defs d ON dc.command_code IN ('LST ' || d.group_code, 'MOD ' || d.group_code)
    JOIN public.standard_params sp
      ON sp.standard_path LIKE d.path_prefix || '%'
     AND sp.entry_type = 'parameter'
     AND (dc.operation_type = 'LST' OR sp.access = 'READ_WRITE')
    GROUP BY dc.command_code
)
INSERT INTO public.mml_commands (
    command_name, command_code, category, description, rpc_method,
    target_paths, target_object, group_id, command_name_i18n, require_confirm,
    confirm_msg_i18n, operation_type, logical_name_i18n, source, catalog_protected,
    platform_tags, tree_node_refs, instance_range_meta, help_doc, notes
)
SELECT
    dc.command_name_zh,
    dc.command_code,
    'log',
    dc.logical_name_zh,
    dc.rpc_method,
    COALESCE(cp.target_paths, '[]'::jsonb),
    NULL,
    dc.group_id,
    jsonb_build_object('zh-CN', dc.command_name_zh, 'en-US', dc.command_name_en),
    false,
    '{}'::jsonb,
    dc.operation_type,
    jsonb_build_object('zh-CN', dc.logical_name_zh, 'en-US', dc.logical_name_en),
    'standard',
    true,
    '{}'::jsonb,
    COALESCE(cp.target_paths, '[]'::jsonb),
    '[]'::jsonb,
    '',
    ''
FROM desired_commands dc
LEFT JOIN command_paths cp ON cp.command_code = dc.command_code
ON CONFLICT (command_code) DO UPDATE
SET command_name = EXCLUDED.command_name,
    category = EXCLUDED.category,
    description = EXCLUDED.description,
    rpc_method = EXCLUDED.rpc_method,
    target_paths = EXCLUDED.target_paths,
    target_object = EXCLUDED.target_object,
    group_id = EXCLUDED.group_id,
    command_name_i18n = EXCLUDED.command_name_i18n,
    operation_type = EXCLUDED.operation_type,
    logical_name_i18n = EXCLUDED.logical_name_i18n,
    source = EXCLUDED.source,
    catalog_protected = EXCLUDED.catalog_protected,
    tree_node_refs = EXCLUDED.tree_node_refs,
    deprecated_at = NULL,
    updated_at = NOW();

WITH log_defs(group_code, path_prefix) AS (
    VALUES
        ('SE_RRM_LOG', 'Device.Services.FAPService.{i}.CellConfig.{i}.NR.RrmLogConfig.'),
        ('SE_DUMGR_LOG', 'Device.Services.FAPService.{i}.FAPControl.NR.DumgrProvLog.'),
        ('SE_RLC_LOG', 'Device.Services.FAPService.{i}.FAPControl.NR.RlcLog.'),
        ('SE_RRC_LOG', 'Device.Services.FAPService.{i}.FAPControl.NR.RrcProv.'),
        ('SE_MAC_LOG', 'Device.Services.FAPService.{i}.CellConfig.{i}.NR.MacSchedulerInfo.'),
        ('SE_OTHER_LOG', 'Device.Services.FAPService.{i}.FAPControl.NR.F1apLog.'),
        ('SE_OTHER_LOG', 'Device.Services.FAPService.{i}.FAPControl.NR.GtpuLog.'),
        ('SE_OTHER_LOG', 'Device.Services.FAPService.{i}.FAPControl.NR.PdcpLog.'),
        ('SE_OTHER_LOG', 'Device.Services.FAPService.{i}.CellConfig.{i}.NR.Duf1uLog.')
), target_cmds AS (
    SELECT c.id, c.command_code, c.operation_type
    FROM public.mml_commands c
    WHERE c.command_code IN (
        'LST SE_RRM_LOG', 'MOD SE_RRM_LOG',
        'LST SE_DUMGR_LOG', 'MOD SE_DUMGR_LOG',
        'LST SE_RLC_LOG', 'MOD SE_RLC_LOG',
        'LST SE_RRC_LOG', 'MOD SE_RRC_LOG',
        'LST SE_MAC_LOG', 'MOD SE_MAC_LOG',
        'LST SE_OTHER_LOG', 'MOD SE_OTHER_LOG'
    )
      AND c.deprecated_at IS NULL
), source_paths AS (
    SELECT
        t.id AS command_id,
        t.operation_type,
        sp.id AS standard_path_id,
        sp.standard_path,
        CASE WHEN sp.access = 'READ_WRITE' THEN 'RW' ELSE 'RO' END AS access_type,
        row_number() OVER (PARTITION BY t.id ORDER BY sp.standard_path) AS sort_order
    FROM target_cmds t
    JOIN log_defs d ON t.command_code IN ('LST ' || d.group_code, 'MOD ' || d.group_code)
    JOIN public.standard_params sp
      ON sp.standard_path LIKE d.path_prefix || '%'
     AND sp.entry_type = 'parameter'
    WHERE t.operation_type = 'LST'
       OR (t.operation_type = 'MOD' AND sp.access = 'READ_WRITE')
), ranked_fields AS (
    SELECT
        base_fields.*,
        row_number() OVER (PARTITION BY command_id, base_mml_code ORDER BY standard_path) AS code_rank
    FROM base_fields
), desired_fields AS (
    SELECT
        command_id,
        standard_path_id,
        LEFT(UPPER(regexp_replace(split_part(standard_path, '.', array_length(string_to_array(standard_path, '.'), 1)), '([a-z0-9])([A-Z])', '\1_\2', 'g')), 100) AS mml_code,
        jsonb_build_object(
            'zh-CN', LEFT(UPPER(regexp_replace(split_part(standard_path, '.', array_length(string_to_array(standard_path, '.'), 1)), '([a-z0-9])([A-Z])', '\1_\2', 'g')), 100),
            'en-US', split_part(standard_path, '.', array_length(string_to_array(standard_path, '.'), 1))
        ) AS label_i18n,
        sort_order,
        access_type,
        operation_type
    FROM source_paths
)
INSERT INTO public.mml_command_sub_fields (
    command_id, standard_path_id, mml_code, label_i18n, default_selected,
    is_required, sort_order, access_type, is_supported
)
SELECT
    command_id,
    standard_path_id,
    mml_code,
    label_i18n,
    true,
    operation_type = 'MOD',
    sort_order,
    CASE WHEN operation_type = 'MOD' THEN 'RW' ELSE access_type END,
    true
FROM desired_fields
ON CONFLICT (command_id, standard_path_id) DO UPDATE
SET mml_code = EXCLUDED.mml_code,
    label_i18n = EXCLUDED.label_i18n,
    default_selected = EXCLUDED.default_selected,
    is_required = EXCLUDED.is_required,
    sort_order = EXCLUDED.sort_order,
    access_type = EXCLUDED.access_type,
    is_supported = EXCLUDED.is_supported,
    deprecated_at = NULL,
    updated_at = NOW();

WITH log_prefixes(path_prefix) AS (
    VALUES
        ('Device.Services.FAPService.{i}.CellConfig.{i}.NR.RrmLogConfig.'),
        ('Device.Services.FAPService.{i}.FAPControl.NR.DumgrProvLog.'),
        ('Device.Services.FAPService.{i}.FAPControl.NR.RlcLog.'),
        ('Device.Services.FAPService.{i}.FAPControl.NR.RrcProv.'),
        ('Device.Services.FAPService.{i}.CellConfig.{i}.NR.MacSchedulerInfo.'),
        ('Device.Services.FAPService.{i}.FAPControl.NR.F1apLog.'),
        ('Device.Services.FAPService.{i}.FAPControl.NR.GtpuLog.'),
        ('Device.Services.FAPService.{i}.FAPControl.NR.PdcpLog.'),
        ('Device.Services.FAPService.{i}.CellConfig.{i}.NR.Duf1uLog.')
)
UPDATE public.mml_command_sub_fields sf
SET deprecated_at = NOW(),
    updated_at = NOW()
FROM public.mml_commands c,
     public.standard_params sp,
     log_prefixes lp
WHERE sf.command_id = c.id
  AND sf.standard_path_id = sp.id
  AND c.command_code IN ('LST FAP_SERVICE', 'MOD FAP_SERVICE')
  AND sp.standard_path LIKE lp.path_prefix || '%'
  AND sf.deprecated_at IS NULL;

UPDATE public.mml_command_groups
SET deleted_at = COALESCE(deleted_at, NOW()),
    deprecated_at = COALESCE(deprecated_at, NOW()),
    updated_at = NOW()
WHERE group_code IN (
    'SE_RRM_LOG',
    'SE_DUMGR_LOG',
    'SE_RLC_LOG',
    'SE_RRC_LOG',
    'SE_MAC_LOG',
    'SE_OTHER_LOG'
)
  AND param_version = 'cmcc-td-lte-v2.3';

WITH target_cmds AS (
    SELECT id
    FROM public.mml_commands
    WHERE command_code IN (
        'LST FAP_SERVICE', 'MOD FAP_SERVICE',
        'LST SE_RRM_LOG', 'MOD SE_RRM_LOG',
        'LST SE_DUMGR_LOG', 'MOD SE_DUMGR_LOG',
        'LST SE_RLC_LOG', 'MOD SE_RLC_LOG',
        'LST SE_RRC_LOG', 'MOD SE_RRC_LOG',
        'LST SE_MAC_LOG', 'MOD SE_MAC_LOG',
        'LST SE_OTHER_LOG', 'MOD SE_OTHER_LOG'
    )
), refreshed AS (
    SELECT
        t.id,
        COALESCE(jsonb_agg(to_jsonb(sp.standard_path) ORDER BY sf.sort_order, sp.standard_path)
                 FILTER (WHERE sp.standard_path IS NOT NULL), '[]'::jsonb) AS paths
    FROM target_cmds t
    LEFT JOIN public.mml_command_sub_fields sf ON sf.command_id = t.id AND sf.deprecated_at IS NULL
    LEFT JOIN public.standard_params sp ON sp.id = sf.standard_path_id
    GROUP BY t.id
)
UPDATE public.mml_commands c
SET target_paths = r.paths,
    tree_node_refs = r.paths,
    updated_at = NOW()
FROM refreshed r
WHERE c.id = r.id;

-- Add LTE LICENSE management group under 小区服务参数管理（总体）.
WITH parent_group AS (
    SELECT id, path
    FROM public.mml_command_groups
    WHERE group_code = 'chapter:SF'
      AND param_version = 'cmcc-td-lte-v2.3'
      AND deleted_at IS NULL
    LIMIT 1
), upsert_group AS (
    INSERT INTO public.mml_command_groups (
        group_code, group_name_zh, group_name_en, path, param_version,
        display_order, is_active, created_by, name_i18n, source,
        catalog_protected, object_path_template, chapter_code, instance_arity, instance_levels
    )
    SELECT
        'SF_LTE_LICENSE',
        'LICENSE管理',
        'LICENSE Management',
        'SF_LTE_LICENSE'::ltree,
        'cmcc-td-lte-v2.3',
        7,
        true,
        'system',
        '{"zh-CN":"LICENSE管理","en-US":"LICENSE Management"}'::jsonb,
        'standard',
        true,
        'Device.Services.FAPService.{i}.FAPControl.LTE.LICENSE.',
        'SF',
        1,
        ARRAY['FAPService']::text[]
    FROM parent_group
    ON CONFLICT (param_version, group_code) DO UPDATE
    SET group_name_zh = EXCLUDED.group_name_zh,
        group_name_en = EXCLUDED.group_name_en,
        path = EXCLUDED.path,
        display_order = EXCLUDED.display_order,
        is_active = EXCLUDED.is_active,
        deleted_at = NULL,
        deprecated_at = NULL,
        name_i18n = EXCLUDED.name_i18n,
        source = EXCLUDED.source,
        catalog_protected = EXCLUDED.catalog_protected,
        object_path_template = EXCLUDED.object_path_template,
        chapter_code = EXCLUDED.chapter_code,
        instance_arity = EXCLUDED.instance_arity,
        instance_levels = EXCLUDED.instance_levels,
        updated_at = NOW()
    RETURNING id
), target_group AS (
    SELECT id FROM upsert_group
    UNION ALL
    SELECT id FROM public.mml_command_groups
    WHERE group_code = 'SF_LTE_LICENSE'
      AND param_version = 'cmcc-td-lte-v2.3'
      AND deleted_at IS NULL
    LIMIT 1
), cmd_defs(command_code, command_name, logical_name, operation_type, rpc_method, target_object) AS (
    VALUES
        ('LST SF_LTE_LICENSE', '查询 LICENSE管理', 'LICENSE管理', 'LST', 'GetParameterValues', 'Device.Services.FAPService.{i}.FAPControl.LTE.LICENSE.')
)
INSERT INTO public.mml_commands (
    command_name, command_code, category, description, rpc_method, operation_type,
    target_paths, target_object, tree_node_refs, group_id, command_name_i18n,
    logical_name_i18n, source, catalog_protected, help_doc
)
SELECT
    c.command_name,
    c.command_code,
    'MML',
    c.command_name,
    c.rpc_method,
    c.operation_type,
    '[]'::jsonb,
    c.target_object,
    jsonb_build_array(c.target_object),
    g.id,
    jsonb_build_object('zh-CN', c.command_name, 'en-US', c.command_code),
    jsonb_build_object('zh-CN', c.logical_name, 'en-US', c.command_code),
    'standard',
    true,
    ''
FROM cmd_defs c
CROSS JOIN target_group g
ON CONFLICT (command_code) DO UPDATE
SET command_name = EXCLUDED.command_name,
    description = EXCLUDED.description,
    rpc_method = EXCLUDED.rpc_method,
    operation_type = EXCLUDED.operation_type,
    target_object = EXCLUDED.target_object,
    group_id = EXCLUDED.group_id,
    command_name_i18n = EXCLUDED.command_name_i18n,
    logical_name_i18n = EXCLUDED.logical_name_i18n,
    source = EXCLUDED.source,
    catalog_protected = EXCLUDED.catalog_protected,
    deprecated_at = NULL,
    updated_at = NOW();

WITH cmd_defs(command_code, operation_type, direct_prefix) AS (
    VALUES
        ('LST SF_LTE_LICENSE', 'LST', 'Device.Services.FAPService.{i}.FAPControl.LTE.LICENSE.')
), target_cmds AS (
    SELECT
        c.id AS command_id,
        c.command_code,
        d.operation_type,
        d.direct_prefix
    FROM cmd_defs d
    JOIN public.mml_commands c ON c.command_code = d.command_code AND c.deprecated_at IS NULL
), source_paths AS (
    SELECT
        t.command_id,
        t.operation_type,
        sp.id AS standard_path_id,
        sp.standard_path,
        sp.access,
        row_number() OVER (PARTITION BY t.command_id ORDER BY sp.standard_path) AS sort_order
    FROM target_cmds t
    JOIN public.standard_params sp
      ON sp.standard_path LIKE t.direct_prefix || '%'
     AND sp.entry_type = 'parameter'
), base_fields AS (
    SELECT
        command_id,
        standard_path_id,
        standard_path,
        LEFT(UPPER(regexp_replace(
            CASE
                WHEN split_part(standard_path, '.', array_length(string_to_array(standard_path, '.'), 1)) = '{i}'
                    THEN split_part(standard_path, '.', array_length(string_to_array(standard_path, '.'), 1) - 1) || 'Instance'
                ELSE split_part(standard_path, '.', array_length(string_to_array(standard_path, '.'), 1))
            END,
            '([a-z0-9])([A-Z])', '\1_\2', 'g'
        )), 93) AS base_mml_code,
        jsonb_build_object(
            'zh-CN', LEFT(UPPER(regexp_replace(
                CASE
                    WHEN split_part(standard_path, '.', array_length(string_to_array(standard_path, '.'), 1)) = '{i}'
                        THEN split_part(standard_path, '.', array_length(string_to_array(standard_path, '.'), 1) - 1) || 'Instance'
                    ELSE split_part(standard_path, '.', array_length(string_to_array(standard_path, '.'), 1))
                END,
                '([a-z0-9])([A-Z])', '\1_\2', 'g'
            )), 100),
            'en-US', split_part(standard_path, '.', array_length(string_to_array(standard_path, '.'), 1))
        ) AS label_i18n,
        sort_order,
        operation_type
    FROM source_paths
), ranked_fields AS (
    SELECT
        base_fields.*,
        row_number() OVER (PARTITION BY command_id, base_mml_code ORDER BY standard_path) AS code_rank
    FROM base_fields
), desired_fields AS (
    SELECT
        command_id,
        standard_path_id,
        CASE WHEN code_rank > 1 THEN base_mml_code || '_' || UPPER(substr(md5(standard_path), 1, 6)) ELSE base_mml_code END AS mml_code,
        label_i18n,
        sort_order,
        operation_type
    FROM ranked_fields
)
INSERT INTO public.mml_command_sub_fields (
    command_id, standard_path_id, mml_code, label_i18n, default_selected,
    is_required, sort_order, access_type, is_supported
)
SELECT
    command_id,
    standard_path_id,
    mml_code,
    label_i18n,
    true,
    false,
    sort_order,
    'RO',
    true
FROM desired_fields
ON CONFLICT (command_id, standard_path_id) DO UPDATE
SET mml_code = EXCLUDED.mml_code,
    label_i18n = EXCLUDED.label_i18n,
    default_selected = EXCLUDED.default_selected,
    is_required = EXCLUDED.is_required,
    sort_order = EXCLUDED.sort_order,
    access_type = EXCLUDED.access_type,
    is_supported = EXCLUDED.is_supported,
    deprecated_at = NULL,
    updated_at = NOW();

WITH target_cmds AS (
    SELECT id, target_object
    FROM public.mml_commands
    WHERE command_code IN (
        'LST SF_LTE_LICENSE'
    )
), refreshed AS (
    SELECT
        t.id,
        COALESCE(jsonb_agg(to_jsonb(sp.standard_path) ORDER BY sf.sort_order, sp.standard_path)
                 FILTER (WHERE sp.standard_path IS NOT NULL), '[]'::jsonb) AS field_paths,
        t.target_object
    FROM target_cmds t
    LEFT JOIN public.mml_command_sub_fields sf ON sf.command_id = t.id AND sf.deprecated_at IS NULL
    LEFT JOIN public.standard_params sp ON sp.id = sf.standard_path_id
    GROUP BY t.id, t.target_object
)
UPDATE public.mml_commands c
SET target_paths = CASE WHEN r.target_object IS NULL THEN r.field_paths ELSE jsonb_build_array(r.target_object) || r.field_paths END,
    tree_node_refs = CASE WHEN r.target_object IS NULL THEN r.field_paths ELSE jsonb_build_array(r.target_object) || r.field_paths END,
    updated_at = NOW()
FROM refreshed r
WHERE c.id = r.id;

UPDATE public.mml_commands
SET deprecated_at = COALESCE(deprecated_at, NOW()),
    updated_at = NOW()
WHERE command_code IN (
    'MOD SF_LTE_LICENSE',
    'ADD SF_LTE_LICENSE_CAPACITY',
    'RMV SF_LTE_LICENSE_CAPACITY'
);

