    group_name_en = EXCLUDED.group_name_en,
    name_i18n = EXCLUDED.name_i18n,
    path = EXCLUDED.path,
    display_order = EXCLUDED.display_order,
    is_active = true,
    source = EXCLUDED.source,
    catalog_protected = EXCLUDED.catalog_protected,
    deleted_at = NULL,
    deprecated_at = NULL,
    updated_at = now();

