    is_required, sort_order, access_type, is_supported
)
SELECT
    c.id,
    sp.id,
    df.mml_code,
    jsonb_build_object('zh-CN', df.label_zh, 'en-US', df.mml_code),
    true,
    c.operation_type = 'MOD',
    df.sort_order,
    CASE WHEN c.operation_type = 'MOD' THEN 'RW' WHEN sp.access = 'READ_WRITE' THEN 'RW' ELSE 'RO' END,
    true
FROM desired_fields df
JOIN public.mml_commands c ON c.command_code = df.command_code AND c.deprecated_at IS NULL
JOIN public.standard_params sp ON sp.standard_path = df.standard_path
ON CONFLICT (command_id, standard_path_id) DO UPDATE
SET mml_code = EXCLUDED.mml_code,
    label_i18n = EXCLUDED.label_i18n,
    default_selected = EXCLUDED.default_selected,
    is_required = EXCLUDED.is_required,
    sort_order = EXCLUDED.sort_order,
    access_type = EXCLUDED.access_type,
    is_supported = EXCLUDED.is_supported,
    deprecated_at = NULL,
    updated_at = now();

WITH target_cmds AS (
    SELECT id
    FROM public.mml_commands
    WHERE command_code IN ('LST STD_TRPATH_G01', 'MOD STD_TRPATH_G01', 'LST STD_TRPATH_G02', 'MOD STD_TRPATH_G02', 'LST STD_TRPATH_G03', 'MOD STD_TRPATH_G03', 'LST STD_TRPATH_G04', 'MOD STD_TRPATH_G04', 'LST STD_TRPATH_G05', 'MOD STD_TRPATH_G05', 'LST STD_TRPATH_G06', 'MOD STD_TRPATH_G06', 'LST STD_TRPATH_G07', 'MOD STD_TRPATH_G07', 'LST STD_TRPATH_G08', 'MOD STD_TRPATH_G08', 'LST STD_TRPATH_G09', 'MOD STD_TRPATH_G09', 'LST STD_TRPATH_G10', 'MOD STD_TRPATH_G10', 'LST STD_TRPATH_G11', 'MOD STD_TRPATH_G11', 'LST STD_TRPATH_G12', 'MOD STD_TRPATH_G12', 'LST STD_TRPATH_G13', 'MOD STD_TRPATH_G13', 'LST STD_TRPATH_G14', 'MOD STD_TRPATH_G14')
      AND deprecated_at IS NULL
), refreshed AS (
    SELECT
        t.id,
        COALESCE(jsonb_agg(to_jsonb(sp.standard_path) ORDER BY sf.sort_order, sp.standard_path)
                 FILTER (WHERE sp.standard_path IS NOT NULL), '[]'::jsonb) AS paths
    FROM target_cmds t
    LEFT JOIN public.mml_command_sub_fields sf ON sf.command_id = t.id AND sf.deprecated_at IS NULL
    LEFT JOIN public.standard_params sp ON sp.id = sf.standard_path_id
    GROUP BY t.id
)
UPDATE public.mml_commands c
SET target_paths = r.paths,
    tree_node_refs = r.paths,
    updated_at = now()
FROM refreshed r
WHERE c.id = r.id;

CREATE OR REPLACE FUNCTION public.cleanup_mml_duplicate_group_bindings() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE public.mml_commands
    SET command_name = CASE
            WHEN command_code = 'LST SO_SUB_01' THEN '查询 GPS信息参数管理'
            ELSE '修改 GPS信息参数管理'
        END,
        command_name_i18n = jsonb_build_object(
            'zh-CN', CASE
                WHEN command_code = 'LST SO_SUB_01' THEN '查询 GPS信息参数管理'
                ELSE '修改 GPS信息参数管理'
            END,
            'en-US', CASE
                WHEN command_code = 'LST SO_SUB_01' THEN 'Query GPS Information Parameters'
                ELSE 'Modify GPS Information Parameters'
            END
        ),
        logical_name_i18n = jsonb_build_object(
            'zh-CN', 'GPS信息参数管理',
            'en-US', 'GPS Information Parameters'
        ),
        updated_at = NOW()
    WHERE command_code IN ('LST SO_SUB_01', 'MOD SO_SUB_01');

    WITH gps_bindings(command_code, standard_path, mml_code, label_zh, sort_order) AS (
        VALUES
            ('LST SO_SUB_01', 'Device.FAP.Synchronization.ClockSourceSyncState', 'CLOCK_SOURCE_SYNC_STATE', 'ClockSourceSyncState', 20),
            ('LST SO_SUB_01', 'Device.FAP.Synchronization.PpsTimeMode', 'PPS_TIME_MODE', 'PpsTimeMode', 21),
            ('LST SO_SUB_01', 'Device.FAP.TFCS.primSrc', 'PRIM_SRC', 'primSrc', 22),
            ('LST SO_SUB_01', 'Device.FAP.TfcsParams.PrimSrc', 'TFCS_PARAMS_PRIM_SRC', 'PrimSrc', 23),
            ('LST SO_SUB_01', 'Device.FAP.TfcsParams.SyncMode', 'SYNC_MODE', 'SyncMode', 24),
            ('MOD SO_SUB_01', 'Device.FAP.Synchronization.PpsTimeMode', 'PPS_TIME_MODE', 'PpsTimeMode', 10),
            ('MOD SO_SUB_01', 'Device.FAP.TFCS.primSrc', 'PRIM_SRC', 'primSrc', 11),
            ('MOD SO_SUB_01', 'Device.FAP.TfcsParams.PrimSrc', 'TFCS_PARAMS_PRIM_SRC', 'PrimSrc', 12),
            ('MOD SO_SUB_01', 'Device.FAP.TfcsParams.SyncMode', 'SYNC_MODE', 'SyncMode', 13)
    )
    INSERT INTO public.mml_command_sub_fields (
        command_id, standard_path_id, mml_code, label_i18n, default_selected,
        is_required, sort_order, access_type, is_supported
    )
    SELECT
        c.id,
        sp.id,
        gb.mml_code,
        jsonb_build_object('zh-CN', gb.label_zh, 'en-US', gb.mml_code),
        true,
        c.operation_type = 'MOD',
        gb.sort_order,
        CASE WHEN c.operation_type = 'MOD' THEN 'RW' WHEN sp.access = 'READ_WRITE' THEN 'RW' ELSE 'RO' END,
        true
    FROM gps_bindings gb
    JOIN public.mml_commands c ON c.command_code = gb.command_code AND c.deprecated_at IS NULL
    JOIN public.standard_params sp ON sp.standard_path = gb.standard_path
    ON CONFLICT (command_id, standard_path_id) DO UPDATE
    SET mml_code = EXCLUDED.mml_code,
        label_i18n = EXCLUDED.label_i18n,
        default_selected = EXCLUDED.default_selected,
        is_required = EXCLUDED.is_required,
        sort_order = EXCLUDED.sort_order,
        access_type = EXCLUDED.access_type,
        is_supported = EXCLUDED.is_supported,
        deprecated_at = NULL,
        updated_at = NOW();

    WITH duplicate_bindings(command_code, standard_path) AS (
        VALUES
            ('LST STD_TRPATH_G01', 'Device.DeviceInfo.AdditionalHardwareVersion'),
            ('LST STD_TRPATH_G01', 'Device.DeviceInfo.AdditionalSoftwareVersion'),
            ('LST STD_TRPATH_G01', 'Device.DeviceInfo.DataModelSpecVersion'),
            ('LST STD_TRPATH_G01', 'Device.DeviceInfo.HardwarePlatform'),
            ('LST STD_TRPATH_G01', 'Device.DeviceInfo.SwUpgrade.FailureCause'),
            ('LST STD_TRPATH_G01', 'Device.DeviceInfo.SwUpgrade.Stage'),
            ('LST STD_TRPATH_G01', 'Device.DeviceInfo.SwUpgrade.Status'),
            ('LST STD_TRPATH_G01', 'Device.DeviceInfo.UserLabel'),
            ('MOD STD_TRPATH_G01', 'Device.DeviceInfo.UserLabel'),
            ('LST STD_TRPATH_G01', 'Device.SoftwareCtrl.SystemCurrentVersion'),
            ('LST STD_TRPATH_G06', 'Device.SoftwareCtrl.ActivateEnable'),
            ('LST STD_TRPATH_G06', 'Device.SoftwareCtrl.ActivateTime'),
            ('LST STD_TRPATH_G06', 'Device.SoftwareCtrl.AutoActivateEnable'),
            ('MOD STD_TRPATH_G06', 'Device.SoftwareCtrl.ActivateEnable'),
            ('MOD STD_TRPATH_G06', 'Device.SoftwareCtrl.ActivateTime'),
            ('MOD STD_TRPATH_G06', 'Device.SoftwareCtrl.AutoActivateEnable'),
            ('LST STD_TRPATH_G06', 'Device.FAP.Synchronization.ClockSourceSyncState'),
            ('LST STD_TRPATH_G06', 'Device.FAP.Synchronization.PpsTimeMode'),
            ('LST STD_TRPATH_G06', 'Device.FAP.TFCS.primSrc'),
            ('LST STD_TRPATH_G06', 'Device.FAP.TfcsParams.PrimSrc'),
            ('LST STD_TRPATH_G06', 'Device.FAP.TfcsParams.SyncMode'),
            ('MOD STD_TRPATH_G06', 'Device.FAP.Synchronization.PpsTimeMode'),
            ('MOD STD_TRPATH_G06', 'Device.FAP.TFCS.primSrc'),
            ('MOD STD_TRPATH_G06', 'Device.FAP.TfcsParams.PrimSrc'),
            ('MOD STD_TRPATH_G06', 'Device.FAP.TfcsParams.SyncMode'),
            ('LST STD_TRPATH_G08', 'Device.Services.FAPService.{i}.CellConfig.LTE.EPC.PLMNList.{i}.CellReservedForOperatorUse'),
            ('MOD STD_TRPATH_G08', 'Device.Services.FAPService.{i}.CellConfig.LTE.EPC.PLMNList.{i}.CellReservedForOperatorUse'),
            ('LST STD_TRPATH_G08', 'Device.Services.FAPService.{i}.CellConfig.LTE.VoLTE.PdcpInitParam.{i}.RohcEn'),
            ('MOD STD_TRPATH_G08', 'Device.Services.FAPService.{i}.CellConfig.LTE.VoLTE.PdcpInitParam.{i}.RohcEn')
    )
    DELETE FROM public.mml_command_sub_fields sf
    USING public.mml_commands c, public.standard_params sp, duplicate_bindings db
    WHERE sf.command_id = c.id
      AND sf.standard_path_id = sp.id
      AND c.command_code = db.command_code
      AND sp.standard_path = db.standard_path;

    DELETE FROM public.mml_commands
    WHERE command_code IN (
        'LST MML350_DEVICE_LAN_HOSTCONFIGMANAGEMENT__IPINTERFACE_NGAPMGMT',
        'LST MML350_DEVICE_LAN_HOSTCONFIGMANAGEMENT__IPINTERFACE_NRCU',
        'LST MML350_DEVICE_LAN_HOSTCONFIGMANAGEMENT__IPINTERFACE_NRDU',
        'LST SN_SUB_01',
        'MOD SN_SUB_01'
    );

    UPDATE public.mml_command_groups g
    SET is_active = false,
        deleted_at = COALESCE(g.deleted_at, NOW()),
        deprecated_at = COALESCE(g.deprecated_at, NOW()),
        updated_at = NOW()
    WHERE g.group_code = 'chapter:SN'
      AND NOT EXISTS (
          SELECT 1
          FROM public.mml_commands c
          WHERE c.group_id = g.id
            AND c.deprecated_at IS NULL
      );

    UPDATE public.mml_commands
    SET logical_name_i18n = jsonb_set(
            COALESCE(logical_name_i18n, '{}'::jsonb),
            '{zh-CN}',
            to_jsonb(CASE
                WHEN command_code IN ('LST DEVICE_INFO_EU', 'MOD DEVICE_INFO_EU')
                    THEN '设备信息-扩展型皮站-扩展单元（EU）参数管理'
                ELSE '设备信息-扩展型皮站-远端单元（RU）参数管理'
            END::text),
            true
        ),
        updated_at = NOW()
    WHERE command_code IN (
        'LST DEVICE_INFO_EU',
        'MOD DEVICE_INFO_EU',
        'LST DEVICE_INFO_RU',
        'MOD DEVICE_INFO_RU'
    );

    WITH target_cmds AS (
        SELECT id
        FROM public.mml_commands
        WHERE command_code IN (
            'LST STD_TRPATH_G01',
            'MOD STD_TRPATH_G01',
            'LST STD_TRPATH_G06',
            'MOD STD_TRPATH_G06',
            'LST STD_TRPATH_G08',
            'MOD STD_TRPATH_G08',
            'LST SO_SUB_01',
            'MOD SO_SUB_01'
        )
    ),
    refreshed AS (
        SELECT
            t.id,
            COALESCE(jsonb_agg(to_jsonb(sp.standard_path) ORDER BY sf.sort_order, sp.standard_path)
                     FILTER (WHERE sp.standard_path IS NOT NULL), '[]'::jsonb) AS paths
        FROM target_cmds t
        LEFT JOIN public.mml_command_sub_fields sf ON sf.command_id = t.id AND sf.deprecated_at IS NULL
        LEFT JOIN public.standard_params sp ON sp.id = sf.standard_path_id
        GROUP BY t.id
    )
    UPDATE public.mml_commands c
    SET target_paths = r.paths,
        tree_node_refs = r.paths,
        updated_at = NOW()
    FROM refreshed r
    WHERE c.id = r.id;
END;
$$;

SELECT public.cleanup_mml_duplicate_group_bindings();

-- RRC timer parameters belong to "RRC参数管理（RRC计时器）" (SH_SUB_03).
-- Keep FAP_SERVICE focused on carrier base config and remove the duplicate bindings.
WITH duplicate_paths(standard_path) AS (
    VALUES
        ('Device.Services.FAPService.{i}.CellConfig.LTE.RAN.RRCTimers.T300'),
        ('Device.Services.FAPService.{i}.CellConfig.LTE.RAN.RRCTimers.T301'),
        ('Device.Services.FAPService.{i}.CellConfig.LTE.RAN.RRCTimers.T302'),
        ('Device.Services.FAPService.{i}.CellConfig.LTE.RAN.RRCTimers.T304EUTRA'),
        ('Device.Services.FAPService.{i}.CellConfig.LTE.RAN.RRCTimers.T304IRAT'),
        ('Device.Services.FAPService.{i}.CellConfig.LTE.RAN.RRCTimers.T310'),
        ('Device.Services.FAPService.{i}.CellConfig.LTE.RAN.RRCTimers.T311'),
        ('Device.Services.FAPService.{i}.CellConfig.LTE.RAN.RRCTimers.T320'),
        ('Device.Services.FAPService.{i}.CellConfig.LTE.RAN.RRCTimers.N310'),
        ('Device.Services.FAPService.{i}.CellConfig.LTE.RAN.RRCTimers.N311')
),
fap_commands AS (
    SELECT id
    FROM public.mml_commands
    WHERE command_code IN ('LST FAP_SERVICE', 'MOD FAP_SERVICE')
)
DELETE FROM public.mml_command_sub_fields sf
USING fap_commands c, public.standard_params sp, duplicate_paths dp
WHERE sf.command_id = c.id
  AND sf.standard_path_id = sp.id
  AND sp.standard_path = dp.standard_path;

WITH duplicate_paths(standard_path) AS (
    VALUES
        ('Device.Services.FAPService.{i}.CellConfig.LTE.RAN.RRCTimers.T300'),
        ('Device.Services.FAPService.{i}.CellConfig.LTE.RAN.RRCTimers.T301'),
        ('Device.Services.FAPService.{i}.CellConfig.LTE.RAN.RRCTimers.T302'),
        ('Device.Services.FAPService.{i}.CellConfig.LTE.RAN.RRCTimers.T304EUTRA'),
        ('Device.Services.FAPService.{i}.CellConfig.LTE.RAN.RRCTimers.T304IRAT'),
        ('Device.Services.FAPService.{i}.CellConfig.LTE.RAN.RRCTimers.T310'),
        ('Device.Services.FAPService.{i}.CellConfig.LTE.RAN.RRCTimers.T311'),
        ('Device.Services.FAPService.{i}.CellConfig.LTE.RAN.RRCTimers.T320'),
        ('Device.Services.FAPService.{i}.CellConfig.LTE.RAN.RRCTimers.N310'),
        ('Device.Services.FAPService.{i}.CellConfig.LTE.RAN.RRCTimers.N311')
)
UPDATE public.mml_commands c
SET target_paths = COALESCE(
        (
            SELECT jsonb_agg(path_value ORDER BY ord)
            FROM jsonb_array_elements_text(c.target_paths) WITH ORDINALITY AS p(path_value, ord)
            WHERE NOT EXISTS (
                SELECT 1
                FROM duplicate_paths dp
                WHERE dp.standard_path = p.path_value
            )
        ),
        '[]'::jsonb
    ),
    tree_node_refs = COALESCE(
        (
            SELECT jsonb_agg(path_value ORDER BY ord)
            FROM jsonb_array_elements_text(c.tree_node_refs) WITH ORDINALITY AS p(path_value, ord)
            WHERE NOT EXISTS (
                SELECT 1
                FROM duplicate_paths dp
                WHERE dp.standard_path = p.path_value
            )
        ),
        '[]'::jsonb
    ),
    updated_at = now()
WHERE c.command_code IN ('LST FAP_SERVICE', 'MOD FAP_SERVICE');

-- 2026-07-23: cover remaining standard TRPath parameters in effective MML groups.
-- Keep this aligned with migrations/seed/000001_init_seed.sql so fresh baseline
-- installs and this incremental script converge to the same catalog.

-- Device basic info: existing bindings were present but marked unsupported.
UPDATE public.mml_command_sub_fields sf
SET is_supported = true,
    access_type = 'RO',
    updated_at = now()
FROM public.mml_commands c
JOIN public.standard_params sp ON true
WHERE sf.command_id = c.id
  AND sp.id = sf.standard_path_id
  AND c.command_code = 'LST DEVICE_INFO'
  AND sp.standard_path IN (
      'Device.DeviceInfo.DataModelSpecVersion',
      'Device.DeviceInfo.HardwarePlatform'
  );

-- Software version control: existing SoftwareCtrl bindings were present but marked unsupported.
UPDATE public.mml_command_sub_fields sf
SET is_supported = true,
    access_type = CASE sp.access WHEN 'READ_WRITE' THEN 'RW' ELSE 'RO' END,
    updated_at = now()
FROM public.mml_commands c
JOIN public.standard_params sp ON true
WHERE sf.command_id = c.id
  AND sp.id = sf.standard_path_id
  AND c.command_code IN ('LST SOFTWARE_CTRL', 'MOD SOFTWARE_CTRL')
  AND sp.standard_path IN (
      'Device.SoftwareCtrl.ActivateEnable',
      'Device.SoftwareCtrl.ActivateTime',
      'Device.SoftwareCtrl.AutoActivateEnable',
      'Device.SoftwareCtrl.SystemCurrentVersion'
  );

-- DeviceInfo.SwUpgrade status fields belong to the software version control query.
WITH wanted(command_code, standard_path, mml_code, zh_label, sort_order) AS (
    VALUES
        ('LST SOFTWARE_CTRL', 'Device.DeviceInfo.SwUpgrade.FailureCause', 'FAILURE_CAUSE', 'FailureCause', 7),
        ('LST SOFTWARE_CTRL', 'Device.DeviceInfo.SwUpgrade.Stage', 'STAGE', 'Stage', 8),
        ('LST SOFTWARE_CTRL', 'Device.DeviceInfo.SwUpgrade.Status', 'STATUS', 'Status', 9)
)
INSERT INTO public.mml_command_sub_fields (
    command_id,
    standard_path_id,
    mml_code,
    label_i18n,
    default_selected,
    is_required,
    sort_order,
    access_type,
    is_supported
)
SELECT c.id,
       sp.id,
       w.mml_code,
       COALESCE(existing.label_i18n, jsonb_build_object('en-US', w.mml_code, 'zh-CN', w.zh_label)),
       true,
       false,
       w.sort_order,
       CASE sp.access WHEN 'READ_WRITE' THEN 'RW' ELSE 'RO' END,
       true
FROM wanted w
JOIN public.mml_commands c ON c.command_code = w.command_code
JOIN public.standard_params sp ON sp.standard_path = w.standard_path
LEFT JOIN LATERAL (
    SELECT sf.label_i18n
    FROM public.mml_command_sub_fields sf
    WHERE sf.standard_path_id = sp.id
    ORDER BY sf.updated_at DESC
    LIMIT 1
) existing ON true
ON CONFLICT (command_id, standard_path_id) DO UPDATE
SET mml_code = EXCLUDED.mml_code,
    label_i18n = EXCLUDED.label_i18n,
    default_selected = EXCLUDED.default_selected,
    is_required = EXCLUDED.is_required,
    sort_order = EXCLUDED.sort_order,
    access_type = EXCLUDED.access_type,
    is_supported = true,
    deprecated_at = NULL,
    updated_at = now();

-- Device.Time.* belongs to the active NTP configuration commands.
WITH wanted(command_code, standard_path, mml_code, zh_label, sort_order) AS (
    VALUES
        ('LST MML350_INTERNETGATEWAYDEVICE__TIME', 'Device.Time.CurrentLocalTime', 'CURRENT_LOCAL_TIME', '本地时间', 13),
        ('LST MML350_INTERNETGATEWAYDEVICE__TIME', 'Device.Time.Enable', 'ENABLE', 'NTP使能开关', 14),
        ('MOD MML350_INTERNETGATEWAYDEVICE__TIME', 'Device.Time.Enable', 'ENABLE', 'NTP使能开关', 13),
        ('LST MML350_INTERNETGATEWAYDEVICE__TIME', 'Device.Time.LocalTimeZone', 'LOCAL_TIME_ZONE', '本地时区', 15),
        ('MOD MML350_INTERNETGATEWAYDEVICE__TIME', 'Device.Time.LocalTimeZone', 'LOCAL_TIME_ZONE', '本地时区', 14),
        ('LST MML350_INTERNETGATEWAYDEVICE__TIME', 'Device.Time.LocalTimeZoneName', 'LOCAL_TIME_ZONE_NAME', '本地时区', 16),
        ('MOD MML350_INTERNETGATEWAYDEVICE__TIME', 'Device.Time.LocalTimeZoneName', 'LOCAL_TIME_ZONE_NAME', '本地时区', 15)
)
INSERT INTO public.mml_command_sub_fields (
    command_id,
    standard_path_id,
    mml_code,
    label_i18n,
    default_selected,
    is_required,
    sort_order,
    access_type,
    is_supported
)
SELECT c.id,
       sp.id,
       w.mml_code,
       COALESCE(existing.label_i18n, jsonb_build_object('en-US', w.mml_code, 'zh-CN', w.zh_label)),
       true,
       false,
       w.sort_order,
       CASE sp.access WHEN 'READ_WRITE' THEN 'RW' ELSE 'RO' END,
       true
FROM wanted w
JOIN public.mml_commands c ON c.command_code = w.command_code
JOIN public.standard_params sp ON sp.standard_path = w.standard_path
LEFT JOIN LATERAL (
    SELECT sf.label_i18n
    FROM public.mml_command_sub_fields sf
    WHERE sf.standard_path_id = sp.id
    ORDER BY sf.updated_at DESC
    LIMIT 1
) existing ON true
ON CONFLICT (command_id, standard_path_id) DO UPDATE
SET mml_code = EXCLUDED.mml_code,
    label_i18n = EXCLUDED.label_i18n,
    default_selected = EXCLUDED.default_selected,
    is_required = EXCLUDED.is_required,
    sort_order = EXCLUDED.sort_order,
    access_type = EXCLUDED.access_type,
    is_supported = true,
    deprecated_at = NULL,
    updated_at = now();

SELECT public.refresh_mml_command_target_paths(c.id)
FROM public.mml_commands c
WHERE c.command_code IN (
    'LST DEVICE_INFO',
    'LST SOFTWARE_CTRL',
    'MOD SOFTWARE_CTRL',
    'LST MML350_INTERNETGATEWAYDEVICE__TIME',
    'MOD MML350_INTERNETGATEWAYDEVICE__TIME'
);

COMMIT;
-- END MML standard TRPath remaining regrouping (20260723)

-- Keepalived/VRRP: restore HA write commands and permission-driven bindings.
BEGIN;

INSERT INTO public.standard_params (
    standard_path, entry_type, access, data_type, change_applies, description
)
VALUES (
    'Device.KeepalivedMgmt.VrrpMgmt.{i}.', 'object', 'READ_WRITE', NULL,
    'Immediate', 'VRRP multi-instance object'
), (
    'Device.KeepalivedMgmt.VrrpMgmt.{i}.VirtualIpList.{i}.', 'object', 'READ_WRITE', NULL,
    'Immediate', 'VRRP virtual IP object'
)
ON CONFLICT (standard_path) DO UPDATE
SET entry_type = 'object',
    access = 'READ_WRITE',
    change_applies = 'Immediate',
    description = EXCLUDED.description,
    updated_at = NOW();

INSERT INTO public.param_mappings (
    param_model_id, standard_path, private_path, entry_type, access,
    change_applies, is_storable, is_active, is_supported, source
)
SELECT pm.id,
    'Device.KeepalivedMgmt.VrrpMgmt.{i}.',
    'Device.KeepalivedMgmt.VrrpMgmt.{i}.',
    'object', 'READ_WRITE', 'Immediate', true, true, true, 'builtin'
FROM public.param_models pm
WHERE pm.name = 'BSC'
UNION ALL
SELECT pm.id,
    'Device.KeepalivedMgmt.VrrpMgmt.{i}.VirtualIpList.{i}.',
    'Device.KeepalivedMgmt.VrrpMgmt.{i}.VirtualIpList.{i}.',
    'object', 'READ_WRITE', 'Immediate', true, true, true, 'builtin'
FROM public.param_models pm
WHERE pm.name = 'BSC'
ON CONFLICT (param_model_id, private_path) DO UPDATE
SET standard_path = EXCLUDED.standard_path,
    entry_type = 'object',
    access = 'READ_WRITE',
    change_applies = 'Immediate',
    is_active = true,
    is_supported = true,
    source = 'builtin',
    updated_at = NOW();

UPDATE public.param_models pm
SET total_entries = stats.total_entries,
    total_objects = stats.total_objects,
    total_params = stats.total_params,
    updated_at = NOW()
FROM (
    SELECT param_model_id,
        COUNT(*) FILTER (WHERE is_active) AS total_entries,
        COUNT(*) FILTER (WHERE is_active AND entry_type = 'object') AS total_objects,
        COUNT(*) FILTER (WHERE is_active AND entry_type = 'parameter') AS total_params
    FROM public.param_mappings
    GROUP BY param_model_id
) stats
WHERE pm.id = stats.param_model_id
  AND pm.name = 'BSC';

WITH desired_params(standard_path, access, data_type) AS (
    VALUES
        ('Device.KeepalivedMgmt.CounterCheck', 'READ_WRITE', 'U_INT'),
        ('Device.KeepalivedMgmt.Enable', 'READ_WRITE', 'U_INT'),
        ('Device.KeepalivedMgmt.LocalUplinkIpAddr', 'READ_ONLY', 'STRING'),
