        ('LST MML350_DEVICE_KEEPALIVEDMGMT__VRRPMGMT', 'Device.KeepalivedMgmt.VrrpMgmt.{i}.AdvertInt', 2),
        ('LST MML350_DEVICE_KEEPALIVEDMGMT__VRRPMGMT', 'Device.KeepalivedMgmt.VrrpMgmt.{i}.DstIpAddr', 3),
