    'LST MML350_DEVICE_KEEPALIVEDMGMT__VRRPMGMT',
    'LST MML350_DEVICE_KEEPALIVEDMGMT__VRRPMGMT_VIRTUALIPLIST'
)
  AND source = 'admin';

WITH refreshed AS (
    SELECT c.id,
           CASE
               WHEN c.operation_type IN ('ADD', 'RMV') AND COALESCE(c.target_object, '') <> ''
                   THEN jsonb_build_array(c.target_object)
               ELSE COALESCE(jsonb_agg(sp.standard_path ORDER BY sf.sort_order, sp.standard_path)
                             FILTER (WHERE sp.standard_path IS NOT NULL), '[]'::jsonb)
           END AS paths
    FROM public.mml_commands c
    LEFT JOIN public.mml_command_sub_fields sf
      ON sf.command_id = c.id AND sf.deprecated_at IS NULL
    LEFT JOIN public.standard_params sp ON sp.id = sf.standard_path_id
    WHERE c.command_code IN (
        'LST MML350_DEVICE_KEEPALIVEDMGMT__KEEPALIVEDMGMT',
        'LST MML350_DEVICE_KEEPALIVEDMGMT__VRRPMGMT',
        'MOD MML350_DEVICE_KEEPALIVEDMGMT__KEEPALIVEDMGMT',
        'MOD MML350_DEVICE_KEEPALIVEDMGMT__VRRPMGMT',
        'ADD MML350_DEVICE_KEEPALIVEDMGMT__VRRPMGMT',
        'RMV MML350_DEVICE_KEEPALIVEDMGMT__VRRPMGMT',
        'LST MML350_DEVICE_KEEPALIVEDMGMT__VRRPMGMT_VIRTUALIPLIST',
        'MOD MML350_DEVICE_KEEPALIVEDMGMT__VRRPMGMT_VIRTUALIPLIST',
        'ADD MML350_DEVICE_KEEPALIVEDMGMT__VRRPMGMT_VIRTUALIPLIST',
        'RMV MML350_DEVICE_KEEPALIVEDMGMT__VRRPMGMT_VIRTUALIPLIST'
    )
    GROUP BY c.id, c.operation_type, c.target_object
)
UPDATE public.mml_commands c
SET target_paths = r.paths,
    tree_node_refs = r.paths,
    updated_at = NOW()
FROM refreshed r
WHERE c.id = r.id;

-- Every multi-instance ADD inherits the effective writable field set of its MOD
-- counterpart. This preserves product-model overrides such as BSC parameters
-- that are READ_WRITE in BSC.xml but READ_ONLY in the shared standard model.
INSERT INTO public.mml_command_sub_fields (
    command_id, standard_path_id, mml_code, label_i18n, default_selected,
    is_required, sort_order, access_type, is_supported
)
SELECT add.id,
       source_sf.standard_path_id,
       source_sf.mml_code,
       source_sf.label_i18n,
       true,
       false,
       source_sf.sort_order,
       source_sf.access_type,
       source_sf.is_supported
FROM public.mml_commands add
JOIN public.mml_commands mod
  ON mod.command_code = 'MOD ' || substr(add.command_code, 5)
 AND mod.deprecated_at IS NULL
JOIN public.mml_command_sub_fields source_sf
  ON source_sf.command_id = mod.id
 AND source_sf.deprecated_at IS NULL
 AND source_sf.access_type = 'RW'
JOIN public.standard_params source_sp
  ON source_sp.id = source_sf.standard_path_id
 AND source_sp.entry_type = 'parameter'
WHERE add.operation_type = 'ADD'
  AND add.deprecated_at IS NULL
  AND COALESCE(add.target_object, '') <> ''
  AND source_sp.standard_path !~ '\{i\}$'
  AND regexp_replace(source_sp.standard_path, '\{i\}\.', '', 'g')
      LIKE regexp_replace(add.target_object, '\{i\}\.', '', 'g') || '%'
  AND regexp_count(source_sp.standard_path, '\{i\}')
      = regexp_count(add.target_object, '\{i\}') + 1
ON CONFLICT (command_id, standard_path_id) DO UPDATE
SET mml_code = EXCLUDED.mml_code,
    label_i18n = EXCLUDED.label_i18n,
    default_selected = EXCLUDED.default_selected,
    is_required = EXCLUDED.is_required,
    sort_order = EXCLUDED.sort_order,
    access_type = EXCLUDED.access_type,
    is_supported = EXCLUDED.is_supported,
    deprecated_at = NULL,
    updated_at = NOW();

-- Commands without a MOD counterpart fall back to shared standard RW fields.
INSERT INTO public.mml_command_sub_fields (
    command_id, standard_path_id, mml_code, label_i18n, default_selected,
    is_required, sort_order, access_type, is_supported
)
SELECT add.id,
       candidate_sp.id,
       LEFT(UPPER(regexp_replace(
           split_part(candidate_sp.standard_path, '.', array_length(string_to_array(candidate_sp.standard_path, '.'), 1)),
           '([a-z0-9])([A-Z])', '\1_\2', 'g'
       )), 91) || '_' || substr(md5(candidate_sp.standard_path), 1, 8),
       jsonb_build_object(
           'zh-CN', COALESCE(NULLIF(candidate_sp.description, ''), split_part(candidate_sp.standard_path, '.', array_length(string_to_array(candidate_sp.standard_path, '.'), 1))),
           'en-US', split_part(candidate_sp.standard_path, '.', array_length(string_to_array(candidate_sp.standard_path, '.'), 1))
       ),
       true,
       false,
       row_number() OVER (PARTITION BY add.id ORDER BY candidate_sp.standard_path),
       'RW',
       true
FROM public.mml_commands add
JOIN public.standard_params candidate_sp
  ON candidate_sp.entry_type = 'parameter'
 AND candidate_sp.access = 'READ_WRITE'
 AND candidate_sp.standard_path !~ '\{i\}$'
 AND regexp_replace(candidate_sp.standard_path, '\{i\}\.', '', 'g')
     LIKE regexp_replace(add.target_object, '\{i\}\.', '', 'g') || '%'
 AND regexp_count(candidate_sp.standard_path, '\{i\}')
     = regexp_count(add.target_object, '\{i\}') + 1
WHERE add.operation_type = 'ADD'
  AND add.deprecated_at IS NULL
  AND COALESCE(add.target_object, '') <> ''
  AND NOT EXISTS (
      SELECT 1
      FROM public.mml_commands mod
      WHERE mod.command_code = 'MOD ' || substr(add.command_code, 5)
        AND mod.deprecated_at IS NULL
  )
ON CONFLICT (command_id, standard_path_id) DO UPDATE
SET mml_code = EXCLUDED.mml_code,
    label_i18n = EXCLUDED.label_i18n,
    default_selected = EXCLUDED.default_selected,
    is_required = EXCLUDED.is_required,
    sort_order = EXCLUDED.sort_order,
    access_type = EXCLUDED.access_type,
    is_supported = EXCLUDED.is_supported,
    deprecated_at = NULL,
    updated_at = NOW();

WITH refreshed AS (
    SELECT c.id,
           COALESCE(
               jsonb_agg(sp.standard_path ORDER BY sf.sort_order, sp.standard_path)
                   FILTER (WHERE sp.standard_path IS NOT NULL),
               '[]'::jsonb
           ) AS paths
    FROM public.mml_commands c
    LEFT JOIN public.mml_command_sub_fields sf
      ON sf.command_id = c.id AND sf.deprecated_at IS NULL
    LEFT JOIN public.standard_params sp ON sp.id = sf.standard_path_id
    WHERE c.operation_type = 'ADD'
      AND c.deprecated_at IS NULL
    GROUP BY c.id
)
UPDATE public.mml_commands c
SET target_paths = r.paths,
    tree_node_refs = r.paths,
    updated_at = NOW()
FROM refreshed r
WHERE c.id = r.id;

COMMIT;

\echo 'MML configuration updates completed.'
\endif
